/**
 * STMS - Teaching & Learning Management System (ប្រព័ន្ធគ្រប់គ្រងការបង្រៀន និងរៀន)
 * សាលាគរុកោសល្យ និងវិក្រឹតការខេត្តក្រចេះ (KTPTTC)
 * Core Controller, Workflows & RBAC State Management
 */

// Global State
let stmsData = {};
let currentUser = null; // Active authenticated user object
let currentRole = 'admin'; // 'admin' | 'trainer' | 'trainee'
let currentView = 'dashboard';
let currentTraineeUser = null; // When in trainee role

// ==========================================================================
// RESILIENT INDEXEDDB STORAGE (FOR LARGE FILES & COMPLETE PERSISTENCE)
// ==========================================================================
const STMS_IDB_NAME = 'KTPTTC_STMS_STORAGE';
const STMS_IDB_VERSION = 1;
let stmsIdbInstance = null;

function getStmsDb() {
  if (stmsIdbInstance) return Promise.resolve(stmsIdbInstance);
  return new Promise((resolve) => {
    if (!window.indexedDB) return resolve(null);
    try {
      const req = indexedDB.open(STMS_IDB_NAME, STMS_IDB_VERSION);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains('files')) {
          db.createObjectStore('files');
        }
        if (!db.objectStoreNames.contains('appdata')) {
          db.createObjectStore('appdata');
        }
      };
      req.onsuccess = (e) => {
        stmsIdbInstance = e.target.result;
        resolve(stmsIdbInstance);
      };
      req.onerror = () => resolve(null);
    } catch (e) {
      resolve(null);
    }
  });
}

async function idbSet(storeName, key, value) {
  try {
    const db = await getStmsDb();
    if (!db) return false;
    return new Promise((resolve) => {
      const tx = db.transaction(storeName, 'readwrite');
      tx.objectStore(storeName).put(value, key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch (e) {
    return false;
  }
}

async function idbGet(storeName, key) {
  try {
    const db = await getStmsDb();
    if (!db) return null;
    return new Promise((resolve) => {
      const tx = db.transaction(storeName, 'readonly');
      const req = tx.objectStore(storeName).get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) {
    return null;
  }
}

// Initialize Application - Enforce Mandatory Login Gate
document.addEventListener('DOMContentLoaded', () => {
  loadData();
  fetchServerStmsData().catch(() => {});
  initAuth();
});

// Universal API Base URL Resolver for STMS
function getStmsApiUrl(endpoint) {
  const p = endpoint.startsWith('/') ? endpoint : '/' + endpoint;
  if (typeof window !== 'undefined' && window.location) {
    const host = (window.location.hostname || '').toLowerCase();
    // On production domain, direct requests to Node.js backend on ktpttc.net (CORS enabled)
    if (host.includes('ktpttc.net') || host.includes('ktpttc.com')) {
      return 'https://ktpttc.net' + p;
    }
  }
  return p;
}

let isSyncingToServer = false;
let serverSyncTimeout = null;

// Async Background Fetch from Server
async function fetchServerStmsData() {
  try {
    const endpoint = getStmsApiUrl('/api/stms/data');
    const res = await fetch(endpoint);
    if (!res.ok) return;
    const json = await res.json();
    if (!json || !json.success) return;

    const srv = json.data;

    // Case 1: If server has no trainees or default users, but local client HAS trainees created by Admin
    // Immediately push client data to the server to seed cloud database
    if (!srv || (typeof srv === 'object' && (!srv.trainees || srv.trainees.length === 0) && (!srv.users || srv.users.length <= 3))) {
      if (Array.isArray(stmsData.trainees) && stmsData.trainees.length > 0) {
        syncToServer();
        return;
      }
    }

    if (srv && typeof srv === 'object') {
      let hasNew = false;

      // 1. Merge Trainees (គរុនិស្សិត)
      if (Array.isArray(srv.trainees) && srv.trainees.length > 0) {
        if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];
        srv.trainees.forEach(srvT => {
          if (!srvT || !srvT.id) return;
          const idx = stmsData.trainees.findIndex(t => t && (t.id === srvT.id || (t.studentId && t.studentId === srvT.studentId)));
          if (idx >= 0) {
            stmsData.trainees[idx] = { ...stmsData.trainees[idx], ...srvT };
          } else {
            stmsData.trainees.push(srvT);
            hasNew = true;
          }
        });
      }

      // 2. Merge Users (Admin, Trainers/Teachers, Staff)
      if (Array.isArray(srv.users) && srv.users.length > 0) {
        if (!Array.isArray(stmsData.users)) stmsData.users = [];
        srv.users.forEach(srvU => {
          if (!srvU || (!srvU.id && !srvU.username)) return;
          const srvUsername = (srvU.username || '').toLowerCase();
          const idx = stmsData.users.findIndex(u => u && (
            (srvU.id && u.id === srvU.id) ||
            (srvUsername && u.username && u.username.toLowerCase() === srvUsername)
          ));
          if (idx >= 0) {
            stmsData.users[idx] = { ...stmsData.users[idx], ...srvU };
          } else {
            stmsData.users.push(srvU);
            hasNew = true;
          }
        });
      }

      // 3. Merge Lessons
      if (Array.isArray(srv.lessons)) {
        if (!Array.isArray(stmsData.lessons)) stmsData.lessons = [];
        srv.lessons.forEach(srvL => {
          if (!stmsData.lessons.some(l => l.id === srvL.id)) {
            stmsData.lessons.unshift(srvL);
            hasNew = true;
          }
        });
      }

      // 4. Merge Videos
      if (Array.isArray(srv.videoLessons)) {
        if (!Array.isArray(stmsData.videoLessons)) stmsData.videoLessons = [];
        srv.videoLessons.forEach(srvV => {
          if (!stmsData.videoLessons.some(v => v.id === srvV.id)) {
            stmsData.videoLessons.unshift(srvV);
            hasNew = true;
          }
        });
      }

      // 5. Merge Assignments
      if (Array.isArray(srv.assignments)) {
        if (!Array.isArray(stmsData.assignments)) stmsData.assignments = [];
        srv.assignments.forEach(srvA => {
          if (!stmsData.assignments.some(a => a.id === srvA.id)) {
            stmsData.assignments.unshift(srvA);
            hasNew = true;
          }
        });
      }

      // 6. Merge Cohorts
      if (Array.isArray(srv.cohorts) && srv.cohorts.length > (stmsData.cohorts || []).length) {
        stmsData.cohorts = srv.cohorts;
        hasNew = true;
      }

      // 7. Merge Custom Classes
      if (Array.isArray(srv.customClasses) && srv.customClasses.length > (stmsData.customClasses || []).length) {
        stmsData.customClasses = srv.customClasses;
        hasNew = true;
      }

      // 8. Merge Subjects & Syllabi
      if (Array.isArray(srv.subjects) && srv.subjects.length > 0) {
        const deletedCodes = Array.isArray(stmsData.deletedSubjectCodes) ? stmsData.deletedSubjectCodes : [];
        if (!Array.isArray(stmsData.subjects)) {
          stmsData.subjects = srv.subjects.filter(s => s && s.code && !deletedCodes.includes(s.code));
          hasNew = true;
        } else {
          srv.subjects.forEach(srvS => {
            if (srvS && srvS.code && !deletedCodes.includes(srvS.code)) {
              const existing = stmsData.subjects.find(s => s && s.code === srvS.code);
              if (!existing) {
                stmsData.subjects.push(srvS);
                hasNew = true;
              }
            }
          });
        }
      }
      if (srv.syllabi && typeof srv.syllabi === 'object') {
        stmsData.syllabi = { ...stmsData.syllabi, ...srv.syllabi };
      }

      // 9. Merge Timetables, Attendance, Reports
      if (Array.isArray(srv.timetables) && srv.timetables.length > 0) {
        stmsData.timetables = srv.timetables;
        hasNew = true;
      }
      if (Array.isArray(srv.attendanceSessions) && srv.attendanceSessions.length > (stmsData.attendanceSessions || []).length) {
        stmsData.attendanceSessions = srv.attendanceSessions;
        hasNew = true;
      }
      if (Array.isArray(srv.teacherAttendance) && srv.teacherAttendance.length > (stmsData.teacherAttendance || []).length) {
        stmsData.teacherAttendance = srv.teacherAttendance;
        hasNew = true;
      }
      if (Array.isArray(srv.teacherReports) && srv.teacherReports.length > (stmsData.teacherReports || []).length) {
        stmsData.teacherReports = srv.teacherReports;
        hasNew = true;
      }
      if (srv.gradebookApprovals && typeof srv.gradebookApprovals === 'object') {
        stmsData.gradebookApprovals = { ...stmsData.gradebookApprovals, ...srv.gradebookApprovals };
      }

      // 10. Merge Books
      if (Array.isArray(srv.books)) {
        if (!Array.isArray(stmsData.books)) stmsData.books = [];
        srv.books.forEach(srvB => {
          if (!stmsData.books.some(b => b.id === srvB.id)) {
            stmsData.books.unshift(srvB);
            hasNew = true;
          }
        });
      }

      if (hasNew) {
        saveData(false);
        if (currentView) renderView(currentView);
      }
    }
  } catch (e) {
    console.warn('Background server fetch deferred:', e);
  }
}

// Load from LocalStorage or Clean Config (No Auto Student Generation)
function loadData() {
  try {
    localStorage.removeItem('ktpttc_stms_data_v1'); // Purge legacy auto-seeded mock data
    const saved = localStorage.getItem('ktpttc_stms_data_v2');
    if (saved) {
      stmsData = JSON.parse(saved);
      if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];
      if (!Array.isArray(stmsData.attendanceSessions)) stmsData.attendanceSessions = [];
      if (!Array.isArray(stmsData.profileRequests)) stmsData.profileRequests = [];
      if (!Array.isArray(stmsData.lessons)) stmsData.lessons = [];
      if (!Array.isArray(stmsData.videoLessons)) stmsData.videoLessons = [];
      if (!Array.isArray(stmsData.assignments)) stmsData.assignments = [];
      if (!Array.isArray(stmsData.onlineClasses)) stmsData.onlineClasses = [];
      if (!Array.isArray(stmsData.teacherAttendance)) stmsData.teacherAttendance = [];
      if (!Array.isArray(stmsData.teacherReports)) stmsData.teacherReports = [];
      if (!stmsData.gradebookApprovals) stmsData.gradebookApprovals = {};

      // Auto-sanitize trainees: clean any binary corrupted entries (e.g. invalid xlsx raw text import)
      const countBefore = stmsData.trainees.length;
      stmsData.trainees = stmsData.trainees.filter(t => {
        if (!t || !t.nameKh) return false;
        const name = String(t.nameKh);
        if (name.includes('PK') && (name.includes('Content_Types') || name.includes('{PK') || /[\x00-\x08\x0E-\x1F\x7F]/.test(name))) return false;
        if (/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(name)) return false;
        if (t.id && (t.id.includes('{PK') || /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(t.id))) return false;
        return true;
      });

      // Purge any mock trainees (auto-seeded mock student profiles)
      const mockStudentIds = ['ktpttc-2026-st-002', 'ktpttc-2026-st-003', 'ktpttc-2026-st-004', 'ktpttc-2026-st-005', 'ktpttc-2026-st-006'];
      const mockStudentNames = ['សុខ ចិន្តា', 'ចាន់ ថា', 'ហេង វិសាល', 'លី ម៉ារីណា', 'កែវ សម្បត្តិ'];
      stmsData.trainees = stmsData.trainees.filter(t => {
        if (!t || !t.nameKh) return false;
        return !mockStudentIds.includes(t.id) && !mockStudentNames.includes(t.nameKh);
      });
      if (stmsData.trainees.length !== countBefore) {
        saveData();
      }

      // Purge mock assignments & lessons & videos & requests
      if (Array.isArray(stmsData.assignments)) {
        stmsData.assignments = stmsData.assignments.filter(a => a && a.id !== 'HW-101' && a.id !== 'HW-102');
      }
      if (Array.isArray(stmsData.lessons)) {
        stmsData.lessons = stmsData.lessons.filter(l => l && l.id !== 'LSN-001' && l.id !== 'LSN-002');
      }
      if (Array.isArray(stmsData.videoLessons)) {
        stmsData.videoLessons = stmsData.videoLessons.filter(v => v && v.id !== 'VID-001');
        stmsData.videoLessons.forEach(v => {
          if (v && v.videoUrl) {
            const ytId = extractYouTubeId(v.videoUrl);
            if (ytId) {
              v.youtubeId = ytId;
              if (!v.embedUrl) v.embedUrl = getYouTubeEmbedUrl(v.videoUrl, true);
              if (!v.watchUrl) v.watchUrl = getYouTubeWatchUrl(v.videoUrl);
              if (!v.thumbnail) v.thumbnail = getYouTubeThumbnail(v.videoUrl);
            }
          }
        });
      }
      if (Array.isArray(stmsData.studentRequests)) {
        stmsData.studentRequests = stmsData.studentRequests.filter(r => r && r.id !== 'REQ-001' && r.id !== 'REQ-002');
      }
      if (Array.isArray(stmsData.cohorts)) {
        stmsData.cohorts = stmsData.cohorts.filter(c => c && c.id !== 'C-12P2-G34' && c.id !== 'C-PRE-G34' && c.id !== 'C-INSERVICE-2026');
      }
      if (Array.isArray(stmsData.timetables)) {
        stmsData.timetables = stmsData.timetables.filter(t => t && t.cohortId !== 'C-12P2-G34');
      }
      if (stmsData.library && Array.isArray(stmsData.library.recentBorrows)) {
        stmsData.library.recentBorrows = stmsData.library.recentBorrows.filter(b => b && b.id !== 'BK-3065' && b.id !== 'BK-5646' && b.id !== 'BK-3109');
      }
      if (Array.isArray(stmsData.dailyAttendanceStats) && stmsData.dailyAttendanceStats.some(s => s.present === 96 && s.day === 'ចន្ទ')) {
        stmsData.dailyAttendanceStats = [];
      }
      if (stmsData.gradeDistribution && stmsData.gradeDistribution.A && stmsData.gradeDistribution.A.pct === 41) {
        stmsData.gradeDistribution = {};
      }

      if (!Array.isArray(stmsData.users) || stmsData.users.length === 0) {
        stmsData.users = JSON.parse(JSON.stringify(window.KTPTTC_INITIAL_DATA?.users || []));
      } else {
        // Guarantee every user has username & password defined by Admin
        stmsData.users.forEach(u => {
          if (!u.password) {
            u.password = u.username === 'admin' ? 'admin123' : u.username === 'trainer' ? 'trainer123' : u.username === 'rachana' ? 'rachana123' : 'trainee123';
          }
          if (!u.status) u.status = 'active';
        });

        // Purge mock faculty teachers (only if BOTH mock ID and mock name match)
        const mockFacultyPairs = [
          { id: 'USR-TRN-002', nameKh: 'លោកស្រី ជា រចនា' },
          { id: 'USR-TRN-003', nameKh: 'លោកស្រី ម៉ៅ សុភា' },
          { id: 'USR-TRN-004', nameKh: 'លោក គង់ វិចិត្រ' },
          { id: 'USR-TRN-005', nameKh: 'លោក អ៊ុំ សុវណ្ណ' },
          { id: 'USR-TRN-006', nameKh: 'លោក ព្រុំ សម្បត្តិ' },
          { id: 'USR-TRN-006', nameKh: 'លោក ព្រំ សម្បត្តិ' },
          { id: 'USR-TRN-007', nameKh: 'លោកស្រី នួន ចរិយា' },
          { id: 'USR-TRN-008', nameKh: 'លោក ឡុង វិសិដ្ឋ' }
        ];
        const prevCount = stmsData.users.length;
        stmsData.users = stmsData.users.filter(u => !u || !mockFacultyPairs.some(m => m.id === u.id && m.nameKh === u.nameKh));
        if (stmsData.users.length !== prevCount) {
          saveData();
        }
      }

      if (!stmsData.syllabi || typeof stmsData.syllabi !== 'object') {
        stmsData.syllabi = JSON.parse(JSON.stringify(window.KTPTTC_DEFAULT_SYLLABI || window.KTPTTC_INITIAL_DATA?.syllabi || {}));
      }

      // Ensure subjects, cohorts, and customClasses exist in storage
      if (!Array.isArray(stmsData.subjects)) {
        stmsData.subjects = JSON.parse(JSON.stringify(window.KTPTTC_INITIAL_DATA?.subjects || []));
      }
      if (Array.isArray(stmsData.deletedSubjectCodes) && Array.isArray(stmsData.subjects)) {
        stmsData.subjects = stmsData.subjects.filter(s => s && s.code && !stmsData.deletedSubjectCodes.includes(s.code));
      }
      if (!Array.isArray(stmsData.cohorts) || stmsData.cohorts.length === 0) {
        stmsData.cohorts = JSON.parse(JSON.stringify(window.KTPTTC_INITIAL_DATA?.cohorts || []));
      }
      if (!Array.isArray(stmsData.customClasses)) {
        stmsData.customClasses = [];
      }
      if (!Array.isArray(stmsData.deletedClasses)) {
        stmsData.deletedClasses = [];
      }
    } else {
      stmsData = JSON.parse(JSON.stringify(window.KTPTTC_INITIAL_DATA || {}));
      if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];
      if (!Array.isArray(stmsData.subjects)) stmsData.subjects = [];
      if (!Array.isArray(stmsData.cohorts)) stmsData.cohorts = [];
      if (!Array.isArray(stmsData.customClasses)) stmsData.customClasses = [];
  if (!Array.isArray(stmsData.books)) stmsData.books = [];
  if (stmsData.books.length === 0 && typeof getInitialDigitalBooks === 'function') {
    stmsData.books = getInitialDigitalBooks();
  }
      if (!Array.isArray(stmsData.lessons)) stmsData.lessons = [];
      if (!Array.isArray(stmsData.videoLessons)) stmsData.videoLessons = [];
      if (!Array.isArray(stmsData.assignments)) stmsData.assignments = [];
      if (!Array.isArray(stmsData.onlineClasses)) stmsData.onlineClasses = [];
      if (!Array.isArray(stmsData.teacherAttendance)) stmsData.teacherAttendance = [];
      if (!Array.isArray(stmsData.teacherReports)) stmsData.teacherReports = [];
      if (!stmsData.gradebookApprovals) stmsData.gradebookApprovals = {};
      if (!stmsData.syllabi) stmsData.syllabi = JSON.parse(JSON.stringify(window.KTPTTC_DEFAULT_SYLLABI || window.KTPTTC_INITIAL_DATA?.syllabi || {}));
      saveData();
    }
  } catch (e) {
    console.error('Failed to load storage, using seed data:', e);
    stmsData = JSON.parse(JSON.stringify(window.KTPTTC_INITIAL_DATA || {}));
    if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];
    if (!Array.isArray(stmsData.subjects)) stmsData.subjects = [];
    if (!Array.isArray(stmsData.cohorts)) stmsData.cohorts = [];
    if (!Array.isArray(stmsData.customClasses)) stmsData.customClasses = [];
  if (!Array.isArray(stmsData.books)) stmsData.books = [];
  if (stmsData.books.length === 0 && typeof getInitialDigitalBooks === 'function') {
    stmsData.books = getInitialDigitalBooks();
  }
    if (!Array.isArray(stmsData.lessons)) stmsData.lessons = [];
    if (!Array.isArray(stmsData.videoLessons)) stmsData.videoLessons = [];
    if (!Array.isArray(stmsData.assignments)) stmsData.assignments = [];
    if (!stmsData.syllabi) stmsData.syllabi = JSON.parse(JSON.stringify(window.KTPTTC_DEFAULT_SYLLABI || window.KTPTTC_INITIAL_DATA?.syllabi || {}));
  }

  // Ensure default teacher & student synced collections exist
  ensureSyncedCollections();
  syncAllSubjects();
  syncTraineeStreams();

  // Async restore lessons/files from IndexedDB if any
  idbGet('appdata', 'ktpttc_stms_data_v2').then(idbData => {
    if (idbData && Array.isArray(idbData.lessons) && idbData.lessons.length > (stmsData.lessons || []).length) {
      if (!Array.isArray(stmsData.lessons)) stmsData.lessons = [];
      idbData.lessons.forEach(idbL => {
        if (!stmsData.lessons.some(l => l.id === idbL.id)) {
          stmsData.lessons.unshift(idbL);
        }
      });
      saveData(false);
      if (currentView === 'trainer-portal' || currentView === 'trainee-portal') {
        renderView(currentView);
      }
    }
    if (idbData && Array.isArray(idbData.books) && idbData.books.length > (stmsData.books || []).length) {
      if (!Array.isArray(stmsData.books)) stmsData.books = [];
      idbData.books.forEach(idbB => {
        if (!stmsData.books.some(b => b.id === idbB.id)) {
          stmsData.books.unshift(idbB);
        }
      });
      saveData(false);
    }
  });

  // Async fetch from server
  fetchServerStmsData();
}

// Persist to LocalStorage with Quota Protection, IndexedDB & Background Server Sync
function saveData(syncToServerBool = true) {
  try {
    // 1. If any lesson/assignment has a large fileData, save to IndexedDB store 'files'
    if (Array.isArray(stmsData.lessons)) {
      stmsData.lessons.forEach(l => {
        if (l && l.fileData && l.fileData.length > 50000) {
          idbSet('files', l.id, l.fileData);
        }
      });
    }
    if (Array.isArray(stmsData.assignments)) {
      stmsData.assignments.forEach(a => {
        if (a && a.fileData && a.fileData.length > 50000) {
          idbSet('files', a.id, a.fileData);
        }
      });
    }
    if (Array.isArray(stmsData.books)) {
      stmsData.books.forEach(b => {
        if (b && b.fileData && b.fileData.length > 50000) {
          idbSet('files', b.id, b.fileData);
        }
      });
    }

    // 2. LocalStorage Persistence with Quota Protection
    try {
      localStorage.setItem('ktpttc_stms_data_v2', JSON.stringify(stmsData));
    } catch (quotaErr) {
      console.warn('LocalStorage quota exceeded, optimizing payload with external file references...', quotaErr);
      const safeData = JSON.parse(JSON.stringify(stmsData));
      if (Array.isArray(safeData.lessons)) {
        safeData.lessons.forEach(l => {
          if (l && l.fileData && l.fileData.length > 50000) {
            l.fileData = null;
            l.hasStoredFile = true;
          }
        });
      }
      if (Array.isArray(safeData.assignments)) {
        safeData.assignments.forEach(a => {
          if (a && a.fileData && a.fileData.length > 50000) {
            a.fileData = null;
            a.hasStoredFile = true;
          }
        });
      }
      if (Array.isArray(safeData.books)) {
        safeData.books.forEach(b => {
          if (b && b.fileData && b.fileData.length > 50000) {
            b.fileData = null;
            b.hasStoredFile = true;
          }
        });
      }
      localStorage.setItem('ktpttc_stms_data_v2', JSON.stringify(safeData));
    }

    // 3. Persist complete unstripped snapshot to IndexedDB
    idbSet('appdata', 'ktpttc_stms_data_v2', stmsData);

    updateAlertBadge();

    // 4. Background Server Sync (Only when authenticated or has authentic data)
    if (syncToServerBool) {
      const hasRealData = (Array.isArray(stmsData.trainees) && stmsData.trainees.length > 0) ||
                          (Array.isArray(stmsData.users) && stmsData.users.length > 3);
      if (window.authenticatedUser || hasRealData) {
        if (serverSyncTimeout) clearTimeout(serverSyncTimeout);
        serverSyncTimeout = setTimeout(() => {
          syncToServer();
        }, 1500);
      }
    }
  } catch (e) {
    console.error('Failed to save data:', e);
  }
}

async function syncToServer() {
  if (isSyncingToServer) return;
  isSyncingToServer = true;
  try {
    const syncData = JSON.parse(JSON.stringify(stmsData));
    if (Array.isArray(syncData.lessons)) {
      syncData.lessons.forEach(l => {
        if (l && l.fileData && l.fileData.length > 500000) {
          l.fileData = null;
          l.hasStoredFile = true;
        }
      });
    }
    if (Array.isArray(syncData.assignments)) {
      syncData.assignments.forEach(a => {
        if (a && a.fileData && a.fileData.length > 500000) {
          a.fileData = null;
          a.hasStoredFile = true;
        }
      });
    }
    const endpoint = getStmsApiUrl('/api/stms/sync');
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: syncData })
    });
  } catch (e) {
    // Graceful offline
  } finally {
    isSyncingToServer = false;
  }
}

// Toast Notification
function showToast(message, type = 'info') {
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = 'stms-toast';
  const icon = type === 'success' ? 'fa-check-circle' : type === 'error' ? 'fa-exclamation-circle' : 'fa-info-circle';
  const color = type === 'success' ? '#10b981' : type === 'error' ? '#ef4444' : '#3b82f6';
  
  toast.innerHTML = `<i class="fas ${icon}" style="color:${color}; font-size:1.1rem;"></i> <span>${message}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transition = 'opacity 0.3s ease';
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// ==========================================================================
// AUTHENTICATION & LOGIN GATE CONTROLLER
// ==========================================================================
let authenticatedUser = null;

/**
 * Universally resolve an authentic, fully populated trainee profile record
 * Matches across stmsData.trainees, stmsData.users, and getAllEnteredStudents()
 * strictly preserving the exact student identity without resetting to index 0.
 */
function resolveTraineeRecord(raw) {
  if (!raw) return null;

  // IMPORTANT: Never convert Administrator or Trainer/Teacher accounts to a trainee!
  if (typeof raw === 'object' && (raw.role === 'admin' || raw.role === 'trainer')) {
    return raw;
  }
  
  const traineesList = (typeof getAllEnteredStudents === 'function') 
    ? getAllEnteredStudents() 
    : (stmsData && Array.isArray(stmsData.trainees) ? stmsData.trainees : []);

  let targetId = '';
  let targetStudentId = '';
  let targetUsername = '';
  let targetNameKh = '';
  let targetPhone = '';

  if (typeof raw === 'string') {
    targetId = raw.trim().toLowerCase();
    targetStudentId = targetId;
    targetUsername = targetId;
  } else if (typeof raw === 'object') {
    if (raw.id) targetId = String(raw.id).trim().toLowerCase();
    if (raw.studentId) targetStudentId = String(raw.studentId).trim().toLowerCase();
    if (raw.username) targetUsername = String(raw.username).trim().toLowerCase();
    if (raw.nameKh) targetNameKh = String(raw.nameKh).trim();
    if (raw.phone) targetPhone = String(raw.phone).replace(/\s+/g, '');
  }

  // Find matching trainee record in traineesList
  let matched = null;
  if (Array.isArray(traineesList) && traineesList.length > 0) {
    matched = traineesList.find(t => {
      if (!t) return false;
      const tId = t.id ? String(t.id).trim().toLowerCase() : '';
      const tStudentId = t.studentId ? String(t.studentId).trim().toLowerCase() : '';
      const tUsername = t.username ? String(t.username).trim().toLowerCase() : '';
      const tNameKh = t.nameKh ? String(t.nameKh).trim() : '';
      const tPhone = t.phone ? String(t.phone).replace(/\s+/g, '') : '';

      // 1. Direct ID / Student ID match
      if (targetStudentId && (tId === targetStudentId || tStudentId === targetStudentId)) return true;
      if (targetId && (tId === targetId || tStudentId === targetId)) return true;

      // 2. If raw was a user account from stmsData.users (e.g. USR-STU-002)
      if (typeof raw === 'object' && raw.id && String(raw.id).startsWith('USR-STU-')) {
        const uRecord = (stmsData.users || []).find(u => u && u.id === raw.id);
        if (uRecord) {
          const uSid = uRecord.studentId ? String(uRecord.studentId).trim().toLowerCase() : '';
          const uUname = uRecord.username ? String(uRecord.username).trim().toLowerCase() : '';
          const uName = uRecord.nameKh ? String(uRecord.nameKh).trim() : '';
          if (uSid && (tId === uSid || tStudentId === uSid)) return true;
          if (uUname && tUsername && tUsername === uUname) return true;
          if (uName && tNameKh && tNameKh === uName) return true;
        }
      }

      // 3. Username match
      if (targetUsername && (tUsername === targetUsername || tId === targetUsername)) return true;

      // 4. Khmer Name match
      if (targetNameKh && tNameKh && tNameKh === targetNameKh) return true;

      // 5. Phone match
      if (targetPhone && tPhone && targetPhone.length >= 8 && tPhone === targetPhone) return true;

      return false;
    });
  }

  // 6. Cross-reference with stmsData.users if not matched yet
  if (!matched && stmsData && Array.isArray(stmsData.users)) {
    const linkedUser = stmsData.users.find(u => 
      u && (
        (targetUsername && u.username && String(u.username).trim().toLowerCase() === targetUsername) ||
        (targetId && u.username && String(u.username).trim().toLowerCase() === targetId) ||
        (targetId && u.id && String(u.id).trim().toLowerCase() === targetId) ||
        (targetStudentId && u.studentId && String(u.studentId).trim().toLowerCase() === targetStudentId) ||
        (targetNameKh && u.nameKh && String(u.nameKh).trim() === targetNameKh)
      )
    );
    if (linkedUser) {
      const uSid = linkedUser.studentId ? String(linkedUser.studentId).trim().toLowerCase() : '';
      if (uSid && Array.isArray(traineesList)) {
        matched = traineesList.find(t => t && String(t.id).trim().toLowerCase() === uSid);
      }
      if (!matched && linkedUser.nameKh && Array.isArray(traineesList)) {
        matched = traineesList.find(t => t && t.nameKh && t.nameKh.trim() === linkedUser.nameKh.trim());
      }
      if (!matched) {
        matched = linkedUser;
      }
    }
  }

  if (matched) {
    const merged = {
      ...(typeof raw === 'object' ? raw : {}),
      ...matched,
      id: matched.id,
      studentId: matched.id,
      nameKh: matched.nameKh || (typeof raw === 'object' ? raw.nameKh : ''),
      nameEn: matched.nameEn || (typeof raw === 'object' ? raw.nameEn : ''),
      photo: matched.photo || (typeof raw === 'object' ? raw.photo : '') || '',
      className: matched.className || (typeof raw === 'object' ? raw.className : ''),
      cohort: matched.cohort || (typeof raw === 'object' ? raw.cohort : ''),
      gender: matched.gender || (typeof raw === 'object' ? raw.gender : 'ប្រុស'),
      dob: matched.dob || (typeof raw === 'object' ? raw.dob : ''),
      role: 'trainee',
      roleLabel: 'គរុនិស្សិត'
    };
    if (!merged.attendanceSummary) {
      merged.attendanceSummary = { rate: 100, present: 0, permission: 0, late: 0, absent: 0 };
    }
    if (!merged.scores) {
      merged.scores = {};
    }
    return merged;
  }

  // If no trainee matched in stmsData.trainees, preserve the raw object faithfully (do not reset to [0])
  if (typeof raw === 'object') {
    return {
      ...raw,
      role: 'trainee',
      roleLabel: raw.roleLabel || 'គរុនិស្សិត'
    };
  }

  return { id: String(raw), role: 'trainee', roleLabel: 'គរុនិស្សិត' };
}
window.resolveTraineeRecord = resolveTraineeRecord;

function initAuth() {
  let savedUser = null;
  let authSession = null;
  try {
    const rawAuth = localStorage.getItem('ktpttc_auth_session');
    if (rawAuth) authSession = JSON.parse(rawAuth);
    const raw = sessionStorage.getItem('ktpttc_current_user') || localStorage.getItem('ktpttc_current_user');
    if (raw) savedUser = JSON.parse(raw);
  } catch (e) {}

  const sessionUser = authSession || savedUser;
  if (!sessionUser || (!sessionUser.username && !sessionUser.id && !sessionUser.role)) {
    showLoginScreen();
    return;
  }

  // Lookup the exact user in stmsData to reflect any fresh changes (e.g. subjects, avatar)
  let freshUser = null;
  if (sessionUser.role === 'trainee') {
    freshUser = resolveTraineeRecord(sessionUser);
  } else {
    if (sessionUser.id) {
      freshUser = (stmsData.users || []).find(u => u && u.id === sessionUser.id);
    }
    if (!freshUser && sessionUser.username) {
      freshUser = (stmsData.users || []).find(u => u && u.username && u.username.toLowerCase() === sessionUser.username.toLowerCase());
    }
    if (!freshUser) {
      freshUser = sessionUser;
    }
  }

  // Enforce global authenticated user
  window.authenticatedUser = freshUser;
  authenticatedUser = freshUser;
  localStorage.setItem('ktpttc_auth_session', JSON.stringify(freshUser));

  if (freshUser.role === 'admin') {
    // Administrator: Can preview roles if explicitly chosen, otherwise admin-portal
    const savedActiveRole = localStorage.getItem('ktpttc_active_role') || 'admin';
    currentRole = savedActiveRole;
    window.currentRole = savedActiveRole;

    let activeProfile;
    if (savedActiveRole === 'trainee') {
      activeProfile = getActiveTraineeProfile();
      currentTraineeUser = activeProfile;
      window.currentTraineeUser = activeProfile;
    } else if (savedActiveRole === 'trainer') {
      activeProfile = getActiveTrainerProfile();
      currentTraineeUser = null;
      window.currentTraineeUser = null;
    } else {
      activeProfile = freshUser;
      currentTraineeUser = null;
      window.currentTraineeUser = null;
    }
    loginSuccess(activeProfile, false);
  } else if (freshUser.role === 'trainer') {
    // Trainer/Teacher: MUST STRICTLY STAY AS THEMSELVES!
    currentRole = 'trainer';
    window.currentRole = 'trainer';
    currentTrainerPreviewId = freshUser.id;
    currentTraineeUser = null;
    window.currentTraineeUser = null;
    localStorage.setItem('ktpttc_active_role', 'trainer');
    localStorage.setItem('ktpttc_profile_trainer', JSON.stringify(freshUser));
    loginSuccess(freshUser, false);
  } else if (freshUser.role === 'trainee') {
    // Trainee/Student: MUST STRICTLY STAY AS THEMSELVES ACROSS RELOAD!
    currentRole = 'trainee';
    window.currentRole = 'trainee';
    const fullTrainee = resolveTraineeRecord(freshUser);
    currentTraineeUser = fullTrainee;
    window.currentTraineeUser = fullTrainee;
    currentUser = fullTrainee;
    localStorage.setItem('ktpttc_active_role', 'trainee');
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(fullTrainee));
    localStorage.setItem('ktpttc_current_user', JSON.stringify(fullTrainee));
    sessionStorage.setItem('ktpttc_current_user', JSON.stringify(fullTrainee));
    loginSuccess(fullTrainee, false);
  } else {
    currentRole = freshUser.role || 'trainer';
    window.currentRole = currentRole;
    loginSuccess(freshUser, false);
  }
}

function showLoginScreen() {
  document.body.classList.remove('role-admin', 'role-trainer', 'role-trainee', 'role-staff', 'role-student', 'is-admin-session');
  const loginOverlay = document.getElementById('stmsLoginScreen');
  const navbar = document.getElementById('stmsNavbar');
  const layout = document.getElementById('stmsAppLayout');
  const navCenterRole = document.getElementById('navCenterRole') || document.querySelector('.nav-center-role');

  if (loginOverlay) loginOverlay.style.display = 'flex';
  if (navbar) navbar.style.display = 'none';
  if (layout) layout.style.display = 'none';
  if (navCenterRole) navCenterRole.style.display = 'none';

  const uInput = document.getElementById('loginUsername');
  const pInput = document.getElementById('loginPassword');
  const errBox = document.getElementById('loginErrorMessage');
  if (uInput) uInput.value = '';
  if (pInput) pInput.value = '';
  if (errBox) errBox.style.display = 'none';
}

async function handleLoginSubmit() {
  const uInput = document.getElementById('loginUsername');
  const pInput = document.getElementById('loginPassword');
  const errBox = document.getElementById('loginErrorMessage');
  const errText = document.getElementById('loginErrorText');
  const btn = document.querySelector('#stmsLoginForm button[type="submit"]') || document.getElementById('btnLoginSubmit');

  const username = uInput ? uInput.value.trim() : '';
  const password = pInput ? pInput.value.trim() : '';

  if (!username || !password) {
    if (errBox && errText) {
      errText.textContent = 'សូមបញ្ចូលឈ្មោះគណនី (Username) និងពាក្យសម្ងាត់ (Password)!';
      errBox.style.display = 'block';
    }
    return;
  }

  if (btn) {
    btn.disabled = true;
    btn.dataset.origText = btn.innerHTML;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> កំពុងផ្ទៀងផ្ទាត់...';
  }
  if (errBox) errBox.style.display = 'none';

  let user = null;

  // 1. Authoritative Cloud Server Authentication (Supports ANY device anywhere)
  try {
    const loginEndpoint = getStmsApiUrl('/api/stms/login');
    const res = await fetch(loginEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    if (res.ok) {
      const json = await res.json();
      if (json && json.success && json.user) {
        user = json.user;
        // Instantly hydrate full system data from server snapshot
        if (json.data && typeof json.data === 'object') {
          stmsData = json.data;
          try {
            localStorage.setItem('ktpttc_stms_data_v2', JSON.stringify(stmsData));
          } catch (e) {}
        }
      }
    } else if (res.status === 401 || res.status === 403 || res.status === 400) {
      const errJson = await res.json().catch(() => ({}));
      if (btn && btn.dataset.origText) {
        btn.disabled = false;
        btn.innerHTML = btn.dataset.origText;
      }
      if (errBox && errText) {
        errText.textContent = errJson.message || 'ឈ្មោះគណនី ឬពាក្យសម្ងាត់មិនត្រឹមត្រូវឡើយ! សូមទាក់ទង Admin ដើម្បីកំណត់ពាក្យសម្ងាត់។';
        errBox.style.display = 'block';
      }
      return;
    }
  } catch (netErr) {
    console.warn('Server login API network error, trying local cache fallback:', netErr);
  }

  // 2. Offline / Local Fallback Verification
  if (!user) {
    const usernameLower = username.toLowerCase();
    const cleanPhone = username.replace(/\s+/g, '');

    user = (stmsData.users || []).find(usr => {
      if (!usr) return false;
      const uName = (usr.username ? String(usr.username) : '').trim().toLowerCase();
      const uId = (usr.id ? String(usr.id) : '').trim().toLowerCase();
      const uStuId = (usr.studentId ? String(usr.studentId) : '').trim().toLowerCase();
      const uEmail = (usr.email ? String(usr.email) : '').trim().toLowerCase();
      const uPhone = (usr.phone ? String(usr.phone) : '').replace(/\s+/g, '');

      const isMatch = (uName === usernameLower || uId === usernameLower || uStuId === usernameLower || uEmail === usernameLower || (cleanPhone && uPhone === cleanPhone));
      if (!isMatch) return false;

      const userPass = usr.password !== undefined && usr.password !== null ? String(usr.password).trim() : '';
      return userPass === password;
    });

    if (!user) {
      const traineesList = (typeof getAllEnteredStudents === 'function') ? getAllEnteredStudents() : (stmsData.trainees || []);
      const matchedTrainee = (traineesList || []).find(t => {
        if (!t) return false;
        const tId = (t.id ? String(t.id) : '').trim().toLowerCase();
        const tStuId = (t.studentId ? String(t.studentId) : '').trim().toLowerCase();
        const tUsername = (t.username ? String(t.username) : '').trim().toLowerCase();
        const tPhone = (t.phone ? String(t.phone) : '').replace(/\s+/g, '');
        const tNameKh = (t.nameKh ? String(t.nameKh) : '').trim();

        const isMatch = (tId === usernameLower || tStuId === usernameLower || tUsername === usernameLower || (cleanPhone && tPhone === cleanPhone) || tNameKh === username);
        if (!isMatch) return false;

        const traineePass = t.password !== undefined && t.password !== null ? String(t.password).trim() : '';
        return (traineePass && traineePass === password) || 
               (tId && tId === password.toLowerCase()) || 
               (password === 'student123' || password === 'ktpttc123');
      });

      if (matchedTrainee) {
        user = {
          id: matchedTrainee.id,
          studentId: matchedTrainee.id,
          username: matchedTrainee.username || matchedTrainee.id.toLowerCase(),
          nameKh: matchedTrainee.nameKh,
          nameEn: matchedTrainee.nameEn,
          role: 'trainee',
          roleLabel: 'គរុនិស្សិត',
          status: 'active',
          ...matchedTrainee
        };
      }
    }
  }

  if (btn && btn.dataset.origText) {
    btn.disabled = false;
    btn.innerHTML = btn.dataset.origText;
  }

  if (!user) {
    if (errBox && errText) {
      errText.textContent = 'ឈ្មោះគណនី ឬពាក្យសម្ងាត់មិនត្រឹមត្រូវឡើយ! សូមទាក់ទង Admin ដើម្បីកំណត់ពាក្យសម្ងាត់។';
      errBox.style.display = 'block';
    }
    return;
  }

  if (user.status === 'disabled') {
    if (errBox && errText) {
      errText.textContent = 'គណនីនេះត្រូវបានផ្អាកដំណើរការដោយ Admin សិក្សាធិការ!';
      errBox.style.display = 'block';
    }
    return;
  }

  if (errBox) errBox.style.display = 'none';

  // Explicitly set active role to the authentic role of this logging-in account
  const userRole = user.role || 'trainer';
  currentRole = userRole;
  window.currentRole = userRole;
  localStorage.setItem('ktpttc_active_role', userRole);

  if (userRole === 'trainee') {
    user = resolveTraineeRecord(user);
    currentTraineeUser = user;
    window.currentTraineeUser = user;
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(user));
  } else if (userRole === 'trainer') {
    currentTrainerPreviewId = user.id;
    window.currentTrainerPreviewId = user.id;
    currentTraineeUser = null;
    window.currentTraineeUser = null;
    localStorage.setItem('ktpttc_profile_trainer', JSON.stringify(user));
  } else if (userRole === 'admin') {
    currentTraineeUser = null;
    window.currentTraineeUser = null;
    window.currentTrainerPreviewId = null;
  }

  window.authenticatedUser = user;
  authenticatedUser = user;
  currentUser = user;
  localStorage.setItem('ktpttc_auth_session', JSON.stringify(user));
  localStorage.setItem('ktpttc_current_user', JSON.stringify(user));
  sessionStorage.setItem('ktpttc_current_user', JSON.stringify(user));
  loginSuccess(user, true);
}

function quickFillLogin(username, password) {
  const uInput = document.getElementById('loginUsername');
  const pInput = document.getElementById('loginPassword');
  if (uInput) uInput.value = username;
  if (pInput) pInput.value = password;
  handleLoginSubmit();
}

function loginSuccess(user, notify = true) {
  if (!user) return;

  // On fresh login (notify === true), update global authenticated user immediately
  if (notify) {
    window.authenticatedUser = user;
    authenticatedUser = user;
    localStorage.setItem('ktpttc_auth_session', JSON.stringify(user));
    currentRole = user.role;
    window.currentRole = user.role;
    localStorage.setItem('ktpttc_active_role', user.role);
  }

  const authUser = window.authenticatedUser || user;
  const isRealAdmin = authUser && authUser.role === 'admin';
  const isAdmin = isRealAdmin;

  // Active role: if real admin on reload / preview, respect savedActiveRole; otherwise strictly user.role
  if (isRealAdmin) {
    if (notify) {
      currentRole = 'admin';
      window.currentRole = 'admin';
      localStorage.setItem('ktpttc_active_role', 'admin');
    } else {
      currentRole = window.currentRole || localStorage.getItem('ktpttc_active_role') || 'admin';
    }
  } else {
    currentRole = user.role;
    window.currentRole = user.role;
    localStorage.setItem('ktpttc_active_role', user.role);
  }

  // If this user is a trainee, resolve full trainee record
  if (user.role === 'trainee') {
    user = resolveTraineeRecord(user);
    currentTraineeUser = user;
    window.currentTraineeUser = user;
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(user));
  } else if (currentRole === 'trainee' && isRealAdmin) {
    // Admin previewing trainee role
    user = getActiveTraineeProfile();
    currentTraineeUser = user;
    window.currentTraineeUser = user;
  } else {
    currentTraineeUser = null;
    window.currentTraineeUser = null;
  }

  if (!window.authenticatedUser) {
    window.authenticatedUser = user;
    authenticatedUser = user;
    localStorage.setItem('ktpttc_auth_session', JSON.stringify(user));
  }

  currentUser = user;
  localStorage.setItem('ktpttc_current_user', JSON.stringify(user));
  sessionStorage.setItem('ktpttc_current_user', JSON.stringify(user));
  localStorage.setItem('ktpttc_active_role', currentRole);
  if (currentRole === 'trainee') {
    currentTraineeUser = user;
    window.currentTraineeUser = user;
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(user));
  }

  const loginOverlay = document.getElementById('stmsLoginScreen');
  const navbar = document.getElementById('stmsNavbar');
  const layout = document.getElementById('stmsAppLayout');

  if (loginOverlay) loginOverlay.style.display = 'none';
  if (navbar) navbar.style.display = 'flex';
  if (layout) layout.style.display = 'flex';

  // Update Navbar Profile Details
  const nameEl = document.getElementById('navbarUserName');
  const roleEl = document.getElementById('navbarUserRole');
  const avatarEl = document.getElementById('navbarUserAvatar');
  if (nameEl) nameEl.textContent = user.nameKh;
  if (roleEl) roleEl.textContent = user.roleLabel || (currentRole === 'trainee' ? 'គរុនិស្សិត' : currentRole === 'trainer' ? 'គ្រូឧទ្ទេស' : 'អ្នកគ្រប់គ្រងប្រព័ន្ធ');
  if (avatarEl) {
    if (user.photo) {
      avatarEl.innerHTML = `<img src="${user.photo}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;" />`;
    } else {
      avatarEl.textContent = user.avatar || (currentRole === 'trainer' ? '👨‍🏫' : currentRole === 'trainee' ? '👨‍🎓' : '👨‍💼');
    }
  }

  // Set body role class for styling rules
  document.body.classList.remove('role-admin', 'role-trainer', 'role-trainee', 'role-staff', 'role-student', 'trainee-mode', 'trainer-mode', 'admin-mode');
  document.body.classList.add(`role-${currentRole}`);
  if (isAdmin) {
    document.body.classList.add('is-admin-session');
  }
  if (currentRole === 'admin') {
    document.body.classList.add('admin-mode');
  } else if (currentRole === 'trainee') {
    document.body.classList.add('trainee-mode');
  } else if (currentRole === 'trainer') {
    document.body.classList.add('trainer-mode');
  }

  // Trainee, Trainer & Admin portal: hide left sidebar for clean standalone portal
  const sidebarAside = document.querySelector('.stms-sidebar') || document.getElementById('stmsSidebar');
  if (sidebarAside) {
    sidebarAside.style.display = 'none';
  }

  // Role Switcher: Permanently hidden for clean production security
  const navCenterRole = document.getElementById('navCenterRole') || document.querySelector('.nav-center-role');
  if (navCenterRole) {
    navCenterRole.style.display = 'none';
  }

  // Set default starting view or check target navigation
  const targetView = sessionStorage.getItem('stms_target_view');
  if (targetView) {
    sessionStorage.removeItem('stms_target_view');
    currentView = targetView;
  } else if (currentRole === 'trainee') {
    currentTraineeUser = user;
    window.currentTraineeUser = user;
    currentView = 'trainee-portal';
  } else if (currentRole === 'trainer') {
    currentView = 'trainer-portal';
  } else if (currentRole === 'admin') {
    currentView = 'admin-portal';
  } else {
    currentView = 'admin-portal';
  }

  renderSidebar();
  renderView(currentView);
  updateAlertBadge();

  if (notify) {
    showToast(`សូមស្វាគមន៍លោក/លោកស្រី «${user.nameKh}» មកកាន់ប្រព័ន្ធ STMS!`, 'success');
  }
}

function handleLogout() {
  if (confirm('តើលោកអ្នកពិតជាចង់ចាកចេញពីប្រព័ន្ធ STMS មែនទេ?')) {
    localStorage.removeItem('ktpttc_current_user');
    sessionStorage.removeItem('ktpttc_current_user');
    localStorage.removeItem('ktpttc_active_role');
    localStorage.removeItem('ktpttc_auth_session');
    localStorage.removeItem('ktpttc_profile_trainer');
    localStorage.removeItem('ktpttc_profile_trainee');
    authenticatedUser = null;
    window.authenticatedUser = null;
    window.currentRole = null;
    window.currentTrainerPreviewId = null;
    currentTrainerPreviewId = null;
    currentTraineeUser = null;
    currentUser = null;
    document.body.classList.remove('role-admin', 'role-trainer', 'role-trainee', 'role-staff', 'role-student', 'trainee-mode', 'trainer-mode', 'admin-mode', 'is-admin-session');
    const sidebarAside = document.querySelector('.stms-sidebar') || document.getElementById('stmsSidebar');
    if (sidebarAside) sidebarAside.style.display = 'flex';
    const navCenterRole = document.getElementById('navCenterRole') || document.querySelector('.nav-center-role');
    if (navCenterRole) navCenterRole.style.display = 'none';
    showLoginScreen();
    showToast('បានចាកចេញពីប្រព័ន្ធដោយជោគជ័យ!', 'info');
  }
}

function toggleLoginPassword() {
  const pInput = document.getElementById('loginPassword');
  const eyeIcon = document.getElementById('eyeIcon');
  const eyeText = document.getElementById('eyeText');
  if (!pInput) return;

  if (pInput.type === 'password') {
    pInput.type = 'text';
    if (eyeIcon) { eyeIcon.classList.remove('fa-eye'); eyeIcon.classList.add('fa-eye-slash'); }
    if (eyeText) eyeText.textContent = 'លាក់';
  } else {
    pInput.type = 'password';
    if (eyeIcon) { eyeIcon.classList.remove('fa-eye-slash'); eyeIcon.classList.add('fa-eye'); }
    if (eyeText) eyeText.textContent = 'បង្ហាញ';
  }
}

// Role Preview Switcher for Administrator
function switchRole(role, notify = true) {
  const authUser = window.authenticatedUser || (function() {
    try {
      const raw = localStorage.getItem('ktpttc_auth_session');
      return raw ? JSON.parse(raw) : null;
    } catch(e) { return null; }
  })();

  const isAdmin = (authUser && authUser.role === 'admin') || (currentUser && currentUser.role === 'admin') || document.body.classList.contains('is-admin-session');

  if (!isAdmin) {
    showToast('មានតែ Administrator ប៉ុណ្ណោះដែលអាចប្តូរទៅមើលសិទ្ធិផ្សេងៗបាន!', 'warning');
    return;
  }

  currentRole = role;
  window.currentRole = role;
  localStorage.setItem('ktpttc_active_role', role);

  // Update body role class
  document.body.classList.remove('role-admin', 'role-trainer', 'role-trainee', 'trainee-mode', 'trainer-mode', 'admin-mode');
  document.body.classList.add(`role-${role}`);
  document.body.classList.add('is-admin-session');
  if (role === 'trainee') {
    document.body.classList.add('trainee-mode');
  } else if (role === 'trainer') {
    document.body.classList.add('trainer-mode');
  } else if (role === 'admin') {
    document.body.classList.add('admin-mode');
  }

  // Hide sidebar for portal mode across all roles
  const sidebarAside = document.querySelector('.stms-sidebar') || document.getElementById('stmsSidebar');
  if (sidebarAside) {
    sidebarAside.style.display = 'none';
  }

  // Update Top Role Switcher Pills
  document.querySelectorAll('.role-tab-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.role === role);
  });

  // Assign Active User Profile preview based on Role
  let previewUser;
  if (role === 'trainee') {
    previewUser = getActiveTraineeProfile();
    currentTraineeUser = previewUser;
    window.currentTraineeUser = previewUser;
    currentUser = { ...previewUser, role: 'trainee', roleLabel: 'គរុនិស្សិត' };
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(previewUser));
  } else if (role === 'trainer') {
    previewUser = getActiveTrainerProfile();
    currentUser = { ...previewUser, role: 'trainer', roleLabel: 'គ្រូឧទ្ទេស' };
  } else {
    previewUser = getActiveAdminProfile();
    currentUser = { ...previewUser, role: 'admin', roleLabel: 'អ្នកគ្រប់គ្រងប្រព័ន្ធ' };
  }

  localStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));
  sessionStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));

  const nameEl = document.getElementById('navbarUserName');
  const roleEl = document.getElementById('navbarUserRole');
  const avatarEl = document.getElementById('navbarUserAvatar');

  if (nameEl) nameEl.textContent = previewUser.nameKh;
  if (roleEl) roleEl.textContent = previewUser.roleLabel || (role === 'trainee' ? 'គរុនិស្សិត' : role === 'trainer' ? 'គ្រូឧទ្ទេស' : 'អ្នកគ្រប់គ្រងប្រព័ន្ធ');
  if (avatarEl) {
    if (previewUser.photo) {
      avatarEl.innerHTML = `<img src="${previewUser.photo}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;" />`;
    } else {
      avatarEl.textContent = previewUser.avatar || (role === 'trainee' ? '👨‍🎓' : role === 'trainer' ? '👨‍🏫' : '👨‍💼');
    }
  }

  // Set default view for role
  if (role === 'trainee') {
    currentTraineeUser = previewUser;
    window.currentTraineeUser = previewUser;
    currentView = 'trainee-portal';
  } else if (role === 'trainer') {
    currentView = 'trainer-portal';
  } else if (role === 'admin') {
    currentView = 'admin-portal';
  } else {
    currentView = 'admin-portal';
  }

  renderSidebar();
  renderView(currentView);

  if (notify) {
    showToast(`កំពុងមើលក្នុងនាម៖ ${previewUser.roleLabel || role}`, 'info');
  }
}

