function renderTraineesView(container) {
  const allTrainees = Array.isArray(stmsData.trainees) ? stmsData.trainees : [];
  
  // Extract all system classes (cohorts, custom classes, trainees)
  const distinctClasses = getAllSystemClasses();

  // Filter by Class
  let filtered = allTrainees;
  if (currentRosterClassFilter && currentRosterClassFilter !== 'all') {
    filtered = allTrainees.filter(t => t.className === currentRosterClassFilter || t.cohort === currentRosterClassFilter);
  }

  // Sort
  let displayed = [...filtered];
  if (currentRosterSort === 'id-asc') {
    displayed.sort((a, b) => (a.id || '').localeCompare(b.id || '', undefined, { numeric: true }));
  } else if (currentRosterSort === 'id-desc') {
    displayed.sort((b, a) => (b.id || '').localeCompare(a.id || '', undefined, { numeric: true }));
  } else if (currentRosterSort === 'name-asc') {
    displayed.sort((a, b) => (a.nameKh || '').localeCompare(b.nameKh || '', 'km'));
  } else if (currentRosterSort === 'name-desc') {
    displayed.sort((b, a) => (b.nameKh || '').localeCompare(a.nameKh || '', 'km'));
  }

  const totalCount = displayed.length;
  const femaleCount = displayed.filter(t => t.gender === 'ស្រី').length;

  const html = `
    ${currentRole === 'admin' ? `
      <div style="margin-bottom: 14px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
        <a onclick="navigateView('admin-portal')" style="display:inline-flex; align-items:center; gap:8px; color:#1e40af; font-weight:700; text-decoration:none; cursor:pointer; background:#eff6ff; padding:7px 16px; border-radius:8px; border:1px solid #bfdbfe; font-size:0.85rem; transition:all 0.2s;">
          <i class="fas fa-arrow-left"></i> ត្រឡប់ទៅ Admin Portal
        </a>
        <div style="display:flex; gap:8px;">
          <button class="btn btn-primary" style="height:34px; font-size:0.82rem;" onclick="navigateView('trainees')"><i class="fas fa-user-graduate"></i> បញ្ជីរាយនាមសិស្ស</button>
          <button class="btn btn-outline" style="height:34px; font-size:0.82rem;" onclick="navigateView('trainers')"><i class="fas fa-chalkboard-teacher"></i> បញ្ជីរាយនាមគ្រូឧទ្ទេស</button>
        </div>
      </div>
    ` : ''}

    <div class="roster-card">
      <!-- Header Row -->
      <div class="roster-header-row">
        <div class="roster-header-left">
          <h2 class="roster-title">បញ្ជីរាយនាមសិស្សានុសិស្ស</h2>
          <div class="roster-class-stat-wrap">
            <select class="roster-class-select" onchange="handleRosterClassChange(this.value)">
              <option value="all" ${currentRosterClassFilter === 'all' ? 'selected' : ''}>ថ្នាក់ដើម</option>
              ${distinctClasses.map(cls => `<option value="${cls}" ${currentRosterClassFilter === cls ? 'selected' : ''}>${cls}</option>`).join('')}
            </select>
            <div class="roster-stats-text">
              <span>សិស្សសរុប: <strong>${totalCount} នាក់</strong></span>
              <span class="roster-female-count">(ស្រី ${femaleCount} នាក់)</span>
            </div>
          </div>
        </div>
        <div class="roster-header-right">
          <button class="btn btn-outline" onclick="viewTraineeCard()" style="font-size:0.85rem; height:36px; padding:0 12px; border-radius:6px; display:inline-flex; align-items:center; gap:6px; border-color:#2563eb; color:#1d4ed8; font-weight:700;">
            <i class="fas fa-id-card"></i> ប័ណ្ណសម្គាល់ខ្លួន (ID Cards)
          </button>
          <button class="roster-btn-print" onclick="exportOrPrintRoster()">
            <i class="fas fa-print"></i> ទម្រង់បោះពុម្ព និង ទាញយក
          </button>
          <button class="btn btn-outline" onclick="openAdminCohortModal()" style="font-size:0.85rem; height:36px; padding:0 12px; border-radius:6px; display:inline-flex; align-items:center; gap:6px; border-color:#3b82f6; color:#1d4ed8; font-weight:700;">
            <i class="fas fa-school"></i> គ្រប់គ្រងថ្នាក់ / បន្ថែមថ្នាក់
          </button>
          <button class="btn btn-outline" onclick="openBulkImportModal('student')" style="font-size:0.85rem; height:36px; padding:0 12px; border-radius:6px; display:inline-flex; align-items:center; gap:6px; border-color:#10b981; color:#059669; font-weight:700;">
            <i class="fas fa-file-excel"></i> នាំចូល Excel / CSV
          </button>
          <button class="btn btn-primary" onclick="openEnrollModal()" style="font-size:0.85rem; height:36px; padding:0 14px; border-radius:6px; display:inline-flex; align-items:center; gap:6px;">
            <i class="fas fa-user-plus"></i> ចុះឈ្មោះសិស្សថ្មី
          </button>
          <button class="roster-btn-delete-all" onclick="confirmDeleteAllStudents()">
            <i class="fas fa-trash"></i> លុបទាំងអស់
          </button>
        </div>
      </div>

      <!-- Sorting Toolbar Row -->
      <div class="roster-toolbar-row">
        <div class="roster-toolbar-left">
          <span class="roster-toolbar-label"><i class="fas fa-bars"></i> តម្រៀប៖</span>
          <div class="roster-sort-group">
            <button class="roster-sort-btn ${currentRosterSort === 'default' ? 'active' : ''}" onclick="setRosterSort('default')">លំដាប់ដើម</button>
            <button class="roster-sort-btn ${currentRosterSort === 'id-asc' ? 'active' : ''}" onclick="setRosterSort('id-asc')">អ.ល &uarr;</button>
            <button class="roster-sort-btn ${currentRosterSort === 'id-desc' ? 'active' : ''}" onclick="setRosterSort('id-desc')">អ.ល &darr;</button>
            <button class="roster-sort-btn ${currentRosterSort === 'name-asc' ? 'active' : ''}" onclick="setRosterSort('name-asc')">ឈ្មោះ: ក &rarr; អ</button>
            <button class="roster-sort-btn ${currentRosterSort === 'name-desc' ? 'active' : ''}" onclick="setRosterSort('name-desc')">ឈ្មោះ: អ &rarr; ក</button>
          </div>
        </div>
        <div class="roster-toolbar-right">
          <button class="roster-btn-save-order" onclick="saveCurrentRosterOrder()">
            <i class="fas fa-save"></i> រក្សាទុកលំដាប់នេះ
          </button>
        </div>
      </div>

      <!-- Table Section -->
      <div class="roster-table-responsive">
        <table class="roster-table" id="traineesDataTable">
          <thead>
            <tr>
              <th style="width: 45px; text-align: center;">ល.រ</th>
              <th style="width: 140px; text-align: center;">អ.ល</th>
              <th style="min-width: 170px;">គោត្តនាម និងនាម</th>
              <th style="width: 60px; text-align: center;">ភេទ</th>
              <th style="width: 115px; text-align: center;">ថ្ងៃខែឆ្នាំកំណើត</th>
              <th style="width: 60px; text-align: center;">អាយុ</th>
              <th style="min-width: 160px;">ទីកន្លែងកំណើត</th>
              <th style="min-width: 160px;">ឈ្មោះឪពុក និង មុខរបរ</th>
              <th style="min-width: 160px;">ឈ្មោះម្តាយ និង មុខរបរ</th>
              <th style="min-width: 140px; text-align: center;">អាណាព្យាបាល និងមុខរបរ</th>
              <th style="width: 130px; text-align: center;">លេខទូរស័ព្ទអាណាព្យាបាល</th>
              <th style="width: 90px; text-align: center;">សកម្មភាព</th>
            </tr>
          </thead>
          <tbody>
            ${displayed.length === 0 ? `
              <tr>
                <td colspan="12" style="text-align:center; padding:55px 20px; color:#64748b;">
                  <i class="fas fa-user-graduate fa-3x" style="color:#cbd5e1; margin-bottom:14px; display:block;"></i>
                  <div style="font-size:1.1rem; font-weight:700; color:#1e3a8a; margin-bottom:8px;">មិនទាន់មានទិន្នន័យគរុនិស្សិតនៅឡើយទេ</div>
                  <p style="font-size:0.875rem; color:#94a3b8; max-width:520px; margin:0 auto 18px auto; line-height:1.6;">
                    សូមចុចប៊ូតុងខាងក្រោមដើម្បីបង្កើតគណនី ឬចុះឈ្មោះគរុនិស្សិតថ្មី
                  </p>
                  <button class="btn btn-primary" onclick="openEnrollModal()"><i class="fas fa-user-plus"></i> ចុះឈ្មោះគរុនិស្សិត</button>
                  <button class="btn btn-outline" onclick="openBulkImportModal('student')" style="margin-left:8px; border-color:#10b981; color:#059669; font-weight:700;"><i class="fas fa-file-excel"></i> នាំចូល Excel / CSV</button>
                </td>
              </tr>
            ` : displayed.map((t, idx) => {
              const fatherStr = formatParentDisplay(t.parents?.fatherName, t.parents?.fatherJob);
              const motherStr = formatParentDisplay(t.parents?.motherName, t.parents?.motherJob);
              const guardianStr = formatParentDisplay(t.parents?.guardianName, t.parents?.guardianJob);
              const parentPhone = (t.parentPhone || t.phone || t.parents?.phone || '-').trim() || '-';
              const ageVal = t.age || calculateAgeFromDob(t.dob);

              return `
                <tr data-trainee-row="${t.id}">
                  <td style="text-align: center; font-weight: 600;">${idx + 1}</td>
                  <td><span class="roster-id-tag">${t.id}</span></td>
                  <td>
                    <div class="roster-student-cell">
                      <div class="roster-student-avatar">
                        ${getUserPhoto(t) ? `<img src="${getUserPhoto(t)}" alt="${t.nameKh}" onerror="this.outerHTML='${t.gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓'}'">` : (t.gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓')}
                      </div>
                      <span class="roster-student-name">${t.nameKh}</span>
                    </div>
                  </td>
                  <td style="text-align: center;">${t.gender || 'ប្រុស'}</td>
                  <td style="text-align: center;">${formatDobDisplay(t.dob)}</td>
                  <td><span class="roster-age-highlight">${ageVal}</span></td>
                  <td>${formatBirthplaceDisplay(t)}</td>
                  <td>${fatherStr}</td>
                  <td>${motherStr}</td>
                  <td style="text-align: ${guardianStr === '-' ? 'center' : 'left'};">${guardianStr}</td>
                  <td style="text-align: center;">${parentPhone}</td>
                  <td>
                    <div class="roster-action-group">
                      <button class="roster-action-btn" style="color:#2563eb; border-color:#93c5fd;" onclick="viewTraineeCard('${t.id}')" title="មើលប័ណ្ណសម្គាល់ខ្លួន (ID Card)"><i class="fas fa-id-card"></i></button>
                      <button class="roster-action-btn" style="color:#0d9488; border-color:#99f6e4;" onclick="openAdminTransferStudentModal('${t.id}')" title="ចាត់ថ្នាក់រៀន ផ្ទេរថ្នាក់ &amp; គ្រប់គ្រងស្ថានភាព"><i class="fas fa-exchange-alt"></i></button>
                      <button class="roster-action-btn btn-edit-roster" onclick="openEditStudent('${t.id}')" title="កែប្រែព័ត៌មាន"><i class="fas fa-edit"></i></button>
                      <button class="roster-action-btn btn-delete-roster" onclick="deleteTraineeRecord('${t.id}')" title="លុបទិន្នន័យ"><i class="fas fa-trash"></i></button>
                    </div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;

  container.innerHTML = html;
}

// ==========================================================================
// 2-B. TRAINER PROFILES MANAGEMENT VIEW (បញ្ជីរាយនាមគ្រូឧទ្ទេស និងសាស្ត្រាចារ្យ តាមគំរូ MoEYS)
// ==========================================================================
let currentTrainerRosterSubjectFilter = 'all';
let currentTrainerRosterSort = 'default';

function handleTrainerRosterSubjectChange(val) {
  currentTrainerRosterSubjectFilter = val;
  renderView('trainers');
}

function setTrainerRosterSort(type) {
  currentTrainerRosterSort = type;
  renderView('trainers');
}

function saveCurrentTrainerRosterOrder() {
  const trainers = (stmsData.users || []).filter(u => u.role === 'trainer');
  if (trainers.length === 0) {
    showToast('ពុំមានទិន្នន័យគ្រូឧទ្ទេសសម្រាប់រក្សាទុកលំដាប់ឡើយ', 'warning');
    return;
  }
  let displayed = [...trainers];
  if (currentTrainerRosterSort === 'id-asc') {
    displayed.sort((a, b) => (a.id || '').localeCompare(b.id || '', undefined, { numeric: true }));
  } else if (currentTrainerRosterSort === 'id-desc') {
    displayed.sort((b, a) => (b.id || '').localeCompare(a.id || '', undefined, { numeric: true }));
  } else if (currentTrainerRosterSort === 'name-asc') {
    displayed.sort((a, b) => (a.nameKh || '').localeCompare(b.nameKh || '', 'km'));
  } else if (currentTrainerRosterSort === 'name-desc') {
    displayed.sort((b, a) => (b.nameKh || '').localeCompare(a.nameKh || '', 'km'));
  }
  const nonTrainers = (stmsData.users || []).filter(u => u.role !== 'trainer');
  stmsData.users = [...nonTrainers, ...displayed];
  saveData();
  currentTrainerRosterSort = 'default';
  showToast('បានរក្សាទុកលំដាប់គ្រូឧទ្ទេសថ្មីជោគជ័យ!', 'success');
  renderView('trainers');
}

function confirmDeleteAllTrainers() {
  const trainers = (stmsData.users || []).filter(u => u.role === 'trainer');
  if (trainers.length === 0) {
    showToast('ពុំមានទិន្នន័យគ្រូឧទ្ទេសសម្រាប់លុបឡើយ', 'info');
    return;
  }
  if (!confirm('តើអ្នកពិតជាចង់លុបទិន្នន័យគ្រូឧទ្ទេសទាំងអស់មែនទេ? សកម្មភាពនេះមិនអាចត្រឡប់វិញបានឡើយ!')) {
    return;
  }
  stmsData.users = (stmsData.users || []).filter(u => u.role !== 'trainer');
  saveData();
  showToast('🗑️ បានលុបទិន្នន័យគ្រូឧទ្ទេសទាំងអស់ជោគជ័យ!', 'success');
  renderView('trainers');
}

function exportOrPrintTrainerRoster() {
  const modalHtml = `
    <div class="stms-modal-backdrop" id="printExportTrainerModal" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-window" style="max-width:440px; width:92%; text-align:center; padding:24px 20px;">
        <div style="font-size:1.15rem; font-weight:700; color:#1e3a8a; margin-bottom:12px;">
          <i class="fas fa-print" style="color:#2563eb;"></i> ទម្រង់បោះពុម្ព និង ទាញយកបញ្ជីគ្រូ
        </div>
        <p style="font-size:0.88rem; color:#64748b; margin-bottom:20px;">
          សូមជ្រើសរើសជម្រើសដែលអ្នកចង់ដំណើរការ៖
        </p>
        <div style="display:flex; flex-direction:column; gap:10px;">
          <button class="btn btn-primary" onclick="closeStmsModal(); setTimeout(() => window.print(), 200);" style="height:42px; font-size:0.9rem; justify-content:center;">
            <i class="fas fa-print"></i> បោះពុម្ពជាក្រដាស / PDF (Print Faculty Roster)
          </button>
          <button class="btn btn-success" onclick="closeStmsModal(); exportTeachersCSV();" style="height:42px; font-size:0.9rem; justify-content:center;">
            <i class="fas fa-file-excel"></i> ទាញយកជា Excel / CSV Spreadsheet
          </button>
          <button class="btn btn-outline" onclick="closeStmsModal(); openBulkImportModal('teacher');" style="height:42px; font-size:0.9rem; justify-content:center; border-color:#10b981; color:#047857; font-weight:700;">
            <i class="fas fa-file-import"></i> នាំចូលទិន្នន័យគ្រូពី Excel / CSV (Bulk Import)
          </button>
          <button class="btn btn-outline" onclick="closeStmsModal()" style="height:38px; font-size:0.85rem; justify-content:center;">
            បោះបង់
          </button>
        </div>
      </div>
    </div>
  `;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function renderTrainersView(container) {
  const allTrainers = (stmsData.users || []).filter(u => u.role === 'trainer');
  const subjects = KTPTTC_ALL_SUBJECTS;

  // Filter by Subject
  let filtered = allTrainers;
  if (currentTrainerRosterSubjectFilter && currentTrainerRosterSubjectFilter !== 'all') {
    filtered = allTrainers.filter(t => t.subject === currentTrainerRosterSubjectFilter);
  }

  // Sort
  let displayed = [...filtered];
  if (currentTrainerRosterSort === 'id-asc') {
    displayed.sort((a, b) => (a.id || '').localeCompare(b.id || '', undefined, { numeric: true }));
  } else if (currentTrainerRosterSort === 'id-desc') {
    displayed.sort((b, a) => (b.id || '').localeCompare(a.id || '', undefined, { numeric: true }));
  } else if (currentTrainerRosterSort === 'name-asc') {
    displayed.sort((a, b) => (a.nameKh || '').localeCompare(b.nameKh || '', 'km'));
  } else if (currentTrainerRosterSort === 'name-desc') {
    displayed.sort((b, a) => (b.nameKh || '').localeCompare(a.nameKh || '', 'km'));
  }

  const totalCount = displayed.length;
  const femaleCount = displayed.filter(t => t.gender === 'ស្រី' || (t.nameKh && t.nameKh.includes('ស្រី'))).length;

  const html = `
    ${currentRole === 'admin' ? `
      <div style="margin-bottom: 14px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
        <a onclick="navigateView('admin-portal')" style="display:inline-flex; align-items:center; gap:8px; color:#1e40af; font-weight:700; text-decoration:none; cursor:pointer; background:#eff6ff; padding:7px 16px; border-radius:8px; border:1px solid #bfdbfe; font-size:0.85rem; transition:all 0.2s;">
          <i class="fas fa-arrow-left"></i> ត្រឡប់ទៅ Admin Portal
        </a>
        <div style="display:flex; gap:8px;">
          <button class="btn btn-outline" style="height:34px; font-size:0.82rem;" onclick="navigateView('trainees')"><i class="fas fa-user-graduate"></i> បញ្ជីរាយនាមសិស្ស</button>
          <button class="btn btn-primary" style="height:34px; font-size:0.82rem;" onclick="navigateView('trainers')"><i class="fas fa-chalkboard-teacher"></i> បញ្ជីរាយនាមគ្រូឧទ្ទេស</button>
        </div>
      </div>
    ` : ''}

    <div class="roster-card">
      <!-- Header Row -->
      <div class="roster-header-row">
        <div class="roster-header-left">
          <h2 class="roster-title">បញ្ជីរាយនាមគ្រូឧទ្ទេស និងសាស្ត្រាចារ្យ</h2>
          <div class="roster-class-stat-wrap">
            <select class="roster-class-select" onchange="handleTrainerRosterSubjectChange(this.value)">
              <option value="all" ${currentTrainerRosterSubjectFilter === 'all' ? 'selected' : ''}>មុខវិជ្ជាទាំងអស់</option>
              ${subjects.map(s => `<option value="${s.code}" ${currentTrainerRosterSubjectFilter === s.code ? 'selected' : ''}>${s.code} - ${s.nameKh}</option>`).join('')}
            </select>
            <div class="roster-stats-text">
              <span>គ្រូឧទ្ទេសសរុប: <strong>${totalCount} នាក់</strong></span>
              <span class="roster-female-count">(ស្រី ${femaleCount} នាក់)</span>
            </div>
          </div>
        </div>
        <div class="roster-header-right">
          <button class="roster-btn-print" onclick="exportOrPrintTrainerRoster()">
            <i class="fas fa-print"></i> ទម្រង់បោះពុម្ព និង ទាញយក
          </button>
          <button class="btn btn-outline" onclick="openAdminSubjectsCatalogModal()" style="font-size:0.85rem; height:36px; padding:0 12px; border-radius:6px; display:inline-flex; align-items:center; gap:6px; border-color:#8b5cf6; color:#7c3aed; font-weight:700;">
            <i class="fas fa-book"></i> គ្រប់គ្រងមុខវិជ្ជា
          </button>
          <button class="btn btn-outline" onclick="openBulkImportModal('teacher')" style="font-size:0.85rem; height:36px; padding:0 12px; border-radius:6px; display:inline-flex; align-items:center; gap:6px; border-color:#10b981; color:#059669; font-weight:700;">
            <i class="fas fa-file-excel"></i> នាំចូល Excel / CSV
          </button>
          <button class="btn btn-primary" onclick="openAdminAddTeacherModal()" style="font-size:0.85rem; height:36px; padding:0 14px; border-radius:6px; display:inline-flex; align-items:center; gap:6px;">
            <i class="fas fa-user-plus"></i> ចុះឈ្មោះគ្រូថ្មី
          </button>
          <button class="roster-btn-delete-all" onclick="confirmDeleteAllTrainers()">
            <i class="fas fa-trash"></i> លុបទាំងអស់
          </button>
        </div>
      </div>

      <!-- Sorting Toolbar Row -->
      <div class="roster-toolbar-row">
        <div class="roster-toolbar-left">
          <span class="roster-toolbar-label"><i class="fas fa-bars"></i> តម្រៀប៖</span>
          <div class="roster-sort-group">
            <button class="roster-sort-btn ${currentTrainerRosterSort === 'default' ? 'active' : ''}" onclick="setTrainerRosterSort('default')">លំដាប់ដើម</button>
            <button class="roster-sort-btn ${currentTrainerRosterSort === 'id-asc' ? 'active' : ''}" onclick="setTrainerRosterSort('id-asc')">អ.ល &uarr;</button>
            <button class="roster-sort-btn ${currentTrainerRosterSort === 'id-desc' ? 'active' : ''}" onclick="setTrainerRosterSort('id-desc')">អ.ល &darr;</button>
            <button class="roster-sort-btn ${currentTrainerRosterSort === 'name-asc' ? 'active' : ''}" onclick="setTrainerRosterSort('name-asc')">ឈ្មោះ: ក &rarr; អ</button>
            <button class="roster-sort-btn ${currentTrainerRosterSort === 'name-desc' ? 'active' : ''}" onclick="setTrainerRosterSort('name-desc')">ឈ្មោះ: អ &rarr; ក</button>
          </div>
        </div>
        <div class="roster-toolbar-right">
          <button class="roster-btn-save-order" onclick="saveCurrentTrainerRosterOrder()">
            <i class="fas fa-save"></i> រក្សាទុកលំដាប់នេះ
          </button>
        </div>
      </div>

      <!-- Table Section -->
      <div class="roster-table-responsive">
        <table class="roster-table" id="trainersDataTable">
          <thead>
            <tr>
              <th style="width: 45px; text-align: center;">ល.រ</th>
              <th style="width: 140px; text-align: center;">អ.ល</th>
              <th style="min-width: 170px;">គោត្តនាម និងនាម</th>
              <th style="width: 60px; text-align: center;">ភេទ</th>
              <th style="width: 115px; text-align: center;">ថ្ងៃខែឆ្នាំកំណើត</th>
              <th style="width: 60px; text-align: center;">អាយុ</th>
              <th style="min-width: 160px;">ទីកន្លែងកំណើត</th>
              <th style="min-width: 180px;">មុខវិជ្ជាទទួលបន្ទុក</th>
              <th style="min-width: 190px;">ថ្នាក់ទទួលបន្ទុកបង្រៀន</th>
              <th style="min-width: 160px;">កម្រិតវប្បធម៌ / ឯកទេស</th>
              <th style="width: 130px; text-align: center;">លេខទូរស័ព្ទ</th>
              <th style="min-width: 140px; text-align: center;">ឈ្មោះគណនី Login</th>
              <th style="width: 90px; text-align: center;">សកម្មភាព</th>
            </tr>
          </thead>
          <tbody>
            ${displayed.length === 0 ? `
              <tr>
                <td colspan="13" style="text-align:center; padding:55px 20px; color:#64748b;">
                  <i class="fas fa-chalkboard-teacher fa-3x" style="color:#cbd5e1; margin-bottom:14px; display:block;"></i>
                  <div style="font-size:1.1rem; font-weight:700; color:#1e3a8a; margin-bottom:8px;">មិនទាន់មានទិន្នន័យគ្រូឧទ្ទេសនៅឡើយទេ</div>
                  <p style="font-size:0.875rem; color:#94a3b8; max-width:520px; margin:0 auto 18px auto; line-height:1.6;">
                    សូមចុចប៊ូតុងខាងក្រោមដើម្បីបន្ថែម ឬចុះឈ្មោះគ្រូឧទ្ទេសថ្មី
                  </p>
                  <button class="btn btn-primary" onclick="openAdminAddTeacherModal()"><i class="fas fa-user-plus"></i> ចុះឈ្មោះគ្រូថ្មី</button>
                  <button class="btn btn-outline" onclick="openBulkImportModal('teacher')" style="margin-left:8px; border-color:#10b981; color:#059669; font-weight:700;"><i class="fas fa-file-excel"></i> នាំចូល Excel / CSV</button>
                </td>
              </tr>
            ` : displayed.map((tr, idx) => {
              const subj = subjects.find(s => s.code === tr.subject);
              const ageVal = tr.age || calculateAgeFromDob(tr.dob || '1985-05-15');
              const genderVal = tr.gender || (tr.nameKh && tr.nameKh.includes('ស្រី') ? 'ស្រី' : 'ប្រុស');
              const dobVal = tr.dob ? formatDobDisplay(tr.dob) : '15/05/1985';
              const pobVal = tr.pob || (typeof tr.birthplace === 'object' ? formatBirthplaceDisplay(tr) : tr.birthplace) || 'ខេត្តក្រចេះ';
              const qualVal = tr.qualification || 'អនុបណ្ឌិតគរុកោសល្យ';
              const trClasses = typeof getTrainerAssignedClasses === 'function' ? getTrainerAssignedClasses(tr) : (tr.assignedClasses || tr.classes || []);
              const trPhoto = typeof getUserPhoto === 'function' ? getUserPhoto(tr) : (tr.photo || '');

              return `
                <tr data-trainer-row="${tr.id}">
                  <td style="text-align: center; font-weight: 600;">${idx + 1}</td>
                  <td><span class="roster-id-tag">${tr.id}</span></td>
                  <td>
                    <div class="roster-student-cell">
                      <div class="roster-student-avatar">
                        ${trPhoto ? `<img src="${trPhoto}" alt="${tr.nameKh}" onerror="this.outerHTML='👨‍🏫'">` : (genderVal === 'ស្រី' ? '👩‍🏫' : '👨‍🏫')}
                      </div>
                      <span class="roster-student-name">${tr.nameKh}</span>
                    </div>
                  </td>
                  <td style="text-align: center;">${genderVal}</td>
                  <td style="text-align: center;">${dobVal}</td>
                  <td><span class="roster-age-highlight">${ageVal}</span></td>
                  <td>${pobVal}</td>
                  <td>
                    <div style="font-weight:700; color:#1e40af; font-size:0.85rem;">
                      ${subj ? `${subj.code} • ${subj.nameKh}` : (tr.subject || '-')}
                    </div>
                  </td>
                  <td>
                    <div style="display:flex; flex-wrap:wrap; gap:4px; align-items:center;">
                      ${trClasses.length > 0 
                        ? trClasses.map(c => `<span style="background:#eff6ff; color:#1d4ed8; border:1px solid #bfdbfe; font-size:0.74rem; font-weight:700; padding:2px 7px; border-radius:10px; display:inline-flex; align-items:center; gap:3px;"><i class="fas fa-users" style="font-size:0.65rem;"></i>${c}</span>`).join('') 
                        : `<span style="color:#94a3b8; font-size:0.75rem;">គ្រប់ថ្នាក់</span>`
                      }
                      <button type="button" onclick="openAdminAssignTeacherClassesModal('${tr.id}')" style="background:#f8fafc; border:1px solid #cbd5e1; color:#2563eb; border-radius:6px; cursor:pointer; font-size:0.75rem; padding:2px 6px; display:inline-flex; align-items:center; gap:3px; font-weight:600;" title="ចាត់តាំង ឬកែប្រែថ្នាក់បង្រៀន">
                        <i class="fas fa-edit"></i> កំណត់ថ្នាក់
                      </button>
                    </div>
                  </td>
                  <td>${qualVal}</td>
                  <td style="text-align: center;">${tr.phone || '-'}</td>
                  <td style="text-align: center;">
                    <code style="background:#f1f5f9; padding:2px 8px; border-radius:4px; font-weight:700; color:#0f172a;">${tr.username || '-'}</code>
                  </td>
                  <td>
                    <div class="roster-action-group">
                      <button class="roster-action-btn btn-edit-roster" onclick="openAdminEditTeacherModal('${tr.id}')" title="កែប្រែព័ត៌មាន"><i class="fas fa-edit"></i></button>
                      <button class="roster-action-btn btn-delete-roster" onclick="deleteAdminTeacher('${tr.id}')" title="លុបទិន្នន័យ"><i class="fas fa-trash"></i></button>
                    </div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;

  container.innerHTML = html;
}

function filterTrainerTable(query) {
  const q = (query || '').toLowerCase().trim();
  const rows = document.querySelectorAll('#trainersDataTable tbody tr');
  rows.forEach(r => {
    const text = r.textContent.toLowerCase();
    r.style.display = text.includes(q) ? '' : 'none';
  });
}

// Filter Trainee Table
function filterTraineeTable(query) {
  const q = (query || '').toLowerCase().trim();
  const rows = document.querySelectorAll('#traineesDataTable tbody tr');
  rows.forEach(r => {
    const text = r.textContent.toLowerCase();
    r.style.display = text.includes(q) ? '' : 'none';
  });
}

function filterTraineeByCohort(cohort) {
  const rows = document.querySelectorAll('#traineesDataTable tbody tr');
  rows.forEach(r => {
    if (cohort === 'all' || r.dataset.cohort === cohort) {
      r.style.display = '';
    } else {
      r.style.display = 'none';
    }
  });
}

// Enrollment Modal Controller - Navigates to full standard Add Student Form
function openEnrollModal() {
  window.location.href = 'add-student.html';
}

// Open Edit Student Page
function openEditStudent(id) {
  closeStmsModal();
  window.location.href = `add-student.html?id=${encodeURIComponent(id)}`;
}

// Open Edit Student Selector Modal
function openEditStudentModal() {
  if (!stmsData.trainees || stmsData.trainees.length === 0) {
    showToast('ពុំទាន់មានទិន្នន័យគរុនិស្សិតដើម្បីកែប្រែនៅឡើយទេ! សូមចុះឈ្មោះគរុនិស្សិតជាមុន។', 'warning');
    return;
  }

  const modalHtml = `
    <div class="stms-modal-backdrop" id="editStudentModalBackdrop" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-window" style="max-width:680px; width:95%;">
        <div class="modal-header-bar" style="border-bottom:1px solid #e2e8f0; padding:16px 20px;">
          <div class="modal-header-title" style="font-size:1.05rem; font-weight:700; color:#1e3a8a; display:flex; align-items:center; gap:8px;">
            <i class="fas fa-edit" style="color:#2563eb;"></i> ជ្រើសរើសគរុនិស្សិតដើម្បីកែប្រែព័ត៌មាន
          </div>
          <button class="modal-close-icon" onclick="closeStmsModal()">&times;</button>
        </div>
        <div class="modal-body-scroll" style="padding:18px 20px;">
          <div style="position:relative; margin-bottom:14px;">
            <i class="fas fa-search" style="position:absolute; left:12px; top:13px; color:#94a3b8;"></i>
            <input type="text" id="editStudentSearchInput" class="form-control" placeholder="ស្វែងរកតាមឈ្មោះ, អត្តលេខ, ថ្នាក់រៀន..." oninput="filterEditStudentList(this.value)" style="padding-left:36px; height:42px; border-radius:8px;">
          </div>
          <div id="editStudentListContainer" style="display:flex; flex-direction:column; gap:10px; max-height:380px; overflow-y:auto; padding-right:4px;">
            ${renderEditStudentItems(stmsData.trainees)}
          </div>
        </div>
        <div class="modal-footer-bar" style="background:#f8fafc; border-top:1px solid #e2e8f0; padding:12px 20px; display:flex; justify-content:space-between; align-items:center;">
          <span style="font-size:0.82rem; color:#64748b;">សរុប៖ <strong>${stmsData.trainees.length} នាក់</strong></span>
          <button class="btn btn-outline" onclick="closeStmsModal()">បិទ</button>
        </div>
      </div>
    </div>
  `;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  setTimeout(() => document.getElementById('editStudentSearchInput')?.focus(), 150);
}

function renderEditStudentItems(list) {
  if (!list || list.length === 0) {
    return `<div style="text-align:center; padding:30px 10px; color:#94a3b8;"><i class="fas fa-search fa-2x" style="margin-bottom:8px; display:block; color:#cbd5e1;"></i>រកមិនឃើញគរុនិស្សិតដែលត្រូវនឹងពាក្យស្វែងរកឡើយ</div>`;
  }
  return list.map(t => `
    <div style="display:flex; align-items:center; justify-content:space-between; padding:12px 14px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; transition:all 0.2s;">
      <div style="display:flex; align-items:center; gap:12px;">
        <div style="width:42px; height:42px; border-radius:50%; background:#e2e8f0; overflow:hidden; display:flex; align-items:center; justify-content:center; font-size:1.4rem; flex-shrink:0; border:1px solid #cbd5e1;">
          ${t.photo ? `<img src="${t.photo}" style="width:100%; height:100%; object-fit:cover;" onerror="this.outerHTML='${t.avatar || '👨‍🎓'}'">` : (t.avatar || '👨‍🎓')}
        </div>
        <div>
          <div style="font-weight:700; color:#0f172a; font-size:0.92rem;">
            ${t.nameKh} ${t.nameEn ? `<span style="font-size:0.8rem; font-weight:400; color:#64748b;">(${t.nameEn})</span>` : ''}
          </div>
          <div style="font-size:0.78rem; color:#64748b; margin-top:2px; display:flex; gap:10px;">
            <span><i class="fas fa-id-badge"></i> <code style="color:#2563eb; font-weight:600;">${t.id}</code></span>
            <span><i class="fas fa-chalkboard-teacher"></i> ${t.className || 'ថ្នាក់ ១២+២'}</span>
            <span><i class="fas fa-venus-mars"></i> ${t.gender || 'ប្រុស'}</span>
          </div>
        </div>
      </div>
      <button class="btn btn-primary" onclick="openEditStudent('${t.id}')" style="height:34px; padding:0 14px; font-size:0.82rem; gap:6px; display:inline-flex; align-items:center;">
        <i class="fas fa-edit"></i> កែប្រែព័ត៌មាន
      </button>
    </div>
  `).join('');
}

function filterEditStudentList(query) {
  const q = (query || '').toLowerCase().trim();
  const filtered = stmsData.trainees.filter(t => {
    return (t.nameKh && t.nameKh.toLowerCase().includes(q)) ||
           (t.nameEn && t.nameEn.toLowerCase().includes(q)) ||
           (t.id && t.id.toLowerCase().includes(q)) ||
           (t.className && t.className.toLowerCase().includes(q));
  });
  const container = document.getElementById('editStudentListContainer');
  if (container) container.innerHTML = renderEditStudentItems(filtered);
}

function updateGeneratedId() {
  const type = document.getElementById('enrollType')?.value || '';
  const idEl = document.getElementById('enrollId');
  const code = type.includes('មត្តេយ្យ') ? 'PRE' : type.includes('វិក្រឹត') ? 'VIK' : '12P2';
  const nextIdx = stmsData.trainees.length + 1;
  if (idEl) {
    idEl.value = `KTPTTC-2026-${code}-${String(nextIdx).padStart(3, '0')}`;
    const uEl = document.getElementById('enrollUsername');
    if (uEl) uEl.value = idEl.value;
  }
}

function submitEnrollForm() {
  const id = document.getElementById('enrollId').value;
  const nameKh = document.getElementById('enrollNameKh').value.trim();
  const nameEn = document.getElementById('enrollNameEn').value.trim();
  const gender = document.getElementById('enrollGender').value;
  const dob = document.getElementById('enrollDob').value;
  const phone = document.getElementById('enrollPhone').value.trim();
  const className = document.getElementById('enrollClass').value;
  const trainingType = document.getElementById('enrollType').value;
  const pob = document.getElementById('enrollPob').value.trim();
  const address = document.getElementById('enrollAddress').value.trim();

  const newTrainee = {
    id,
    roll: stmsData.trainees.length + 1,
    nameKh,
    nameEn,
    gender,
    dob,
    phone,
    className,
    cohort: trainingType.includes('បឋម') ? "ថ្នាក់បឋមសិក្សា ១២+២ ជំនាន់ទី ៣៤" : trainingType.includes('មត្តេយ្យ') ? "ថ្នាក់មត្តេយ្យសិក្សា ១២+២ ជំនាន់ទី ៣៤" : "ថ្នាក់វិក្រឹតការគ្រូបង្រៀន និងនាយកសាលា",
    trainingType,
    status: "កំពុងសិក្សា",
    avatar: gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓',
    pob,
    address,
    bacii: {
      examYear: document.getElementById('enrollBacYear').value,
      rollNumber: document.getElementById('enrollBacRoll').value,
      grade: document.getElementById('enrollBacGrade').value
    },
    documents: [
      { name: "សញ្ញាបត្របាក់ឌុប (BacII)", status: "verified" },
      { name: "អត្តសញ្ញាណប័ណ្ណសញ្ជាតិខ្មែរ", status: "verified" },
      { name: "រូបថត 4x6 ឯកសណ្ឋាន", status: "verified" }
    ],
    attendanceSummary: {
      present: 0,
      permission: 0,
      late: 0,
      absent: 0,
      rate: 100.0
    },
    scores: {}
  };

  stmsData.trainees.push(newTrainee);

  // Auto-Provision Trainee User Account if checked
  const createAccount = document.getElementById('enrollCreateAccount')?.checked;
  const username = document.getElementById('enrollUsername')?.value.trim().toLowerCase() || id.toLowerCase();
  const password = document.getElementById('enrollPassword')?.value.trim() || 'ktpttc123';

  if (createAccount) {
    if (!Array.isArray(stmsData.users)) stmsData.users = [];
    const exists = stmsData.users.some(u => u.username.toLowerCase() === username);
    if (!exists) {
      stmsData.users.push({
        id: `USR-STU-${String(stmsData.users.length + 1).padStart(3, '0')}`,
        nameKh,
        nameEn,
        studentId: id,
        username,
        password,
        role: "trainee",
        roleLabel: "គរុនិស្សិត",
        email: phone ? `${username}@student.ktpttc.edu.kh` : "portal@student.ktpttc.edu.kh",
        phone,
        className,
        cohort: newTrainee.cohort,
        status: "active",
        avatar: gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓'
      });
    }
  }

  saveData();
  closeStmsModal();
  showToast(`បានចុះឈ្មោះគរុនិស្សិត «${nameKh}» (${id}) ព្រមទាំងបង្កើតគណនី Login ដោយជោគជ័យ!`, 'success');
  renderView('trainees');
}

// --------------------------------------------------------------------------
// STUDENT & TEACHER PROFILE PHOTO RESOLVER & SYNCHRONIZER
// --------------------------------------------------------------------------

// Grab photo from uploaded image data (student/teacher profile, photoUrl or base64)
function getUserPhoto(u) {
  if (!u) return '';
  if (u.photo && typeof u.photo === 'string' && u.photo.trim() && !u.photo.includes('undefined')) {
    return u.photo.trim();
  }
  
  // 1. If trainee or has studentId
  if (u.role === 'trainee' || u.studentId) {
    const sId = String(u.studentId || u.id || '').trim().toLowerCase();
    const uName = String(u.username || '').trim().toLowerCase();
    const t = (stmsData.trainees || []).find(x => 
      (x.id && String(x.id).trim().toLowerCase() === sId) ||
      (x.studentId && String(x.studentId).trim().toLowerCase() === sId) ||
      (x.username && String(x.username).trim().toLowerCase() === uName) ||
      (x.nameKh && u.nameKh && x.nameKh === u.nameKh)
    );
    if (t && t.photo && typeof t.photo === 'string' && t.photo.trim() && !t.photo.includes('undefined')) {
      return t.photo.trim();
    }
    // Also check stmsData.users for matching trainee photo
    const usr = (stmsData.users || []).find(x => 
      x.role === 'trainee' && x.photo && (
        (x.id && String(x.id).trim().toLowerCase() === sId) ||
        (x.studentId && String(x.studentId).trim().toLowerCase() === sId) ||
        (x.username && String(x.username).trim().toLowerCase() === uName) ||
        (x.nameKh && u.nameKh && x.nameKh === u.nameKh)
      )
    );
    if (usr && usr.photo && typeof usr.photo === 'string' && usr.photo.trim() && !usr.photo.includes('undefined')) {
      return usr.photo.trim();
    }
  }

  // 2. If trainer
  if (u.role === 'trainer') {
    const trId = String(u.id || '').trim().toLowerCase();
    const uName = String(u.username || '').trim().toLowerCase();
    
    // Check teachers in custom list
    if (Array.isArray(stmsData.teachers)) {
      const tr = stmsData.teachers.find(x => 
        (x.id && String(x.id).trim().toLowerCase() === trId) ||
        (x.username && String(x.username).trim().toLowerCase() === uName) ||
        (x.nameKh && u.nameKh && x.nameKh === u.nameKh)
      );
      if (tr && tr.photo && typeof tr.photo === 'string' && tr.photo.trim() && !tr.photo.includes('undefined')) {
        return tr.photo.trim();
      }
    }

    // Check users array for any matching trainer photo
    const usrTr = (stmsData.users || []).find(x => 
      x.role === 'trainer' && x.photo && (
        (x.id && String(x.id).trim().toLowerCase() === trId) ||
        (x.username && String(x.username).trim().toLowerCase() === uName) ||
        (x.nameKh && u.nameKh && x.nameKh === u.nameKh)
      )
    );
    if (usrTr && usrTr.photo && typeof usrTr.photo === 'string' && usrTr.photo.trim() && !usrTr.photo.includes('undefined')) {
      return usrTr.photo.trim();
    }
  }

  return '';
}
window.getUserPhoto = getUserPhoto;

// Synchronize uploaded photos across trainees, teachers, and users collections
function syncPhotosAcrossCollections() {
  if (!stmsData) return;
  if (!Array.isArray(stmsData.users)) stmsData.users = [];
  if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];

  let changed = false;

  stmsData.users.forEach(u => {
    if (!u) return;
    if (u.role === 'trainee') {
      const sId = String(u.studentId || u.id || '').trim().toLowerCase();
      const uName = String(u.username || '').trim().toLowerCase();
      const match = stmsData.trainees.find(t => 
        (t.id && String(t.id).trim().toLowerCase() === sId) ||
        (t.studentId && String(t.studentId).trim().toLowerCase() === sId) ||
        (t.username && String(t.username).trim().toLowerCase() === uName) ||
        (t.nameKh && t.nameKh === u.nameKh)
      );
      if (match) {
        if (!u.photo && match.photo) {
          u.photo = match.photo;
          changed = true;
        } else if (!match.photo && u.photo) {
          match.photo = u.photo;
          changed = true;
        }
      }
    } else if (u.role === 'trainer') {
      if (Array.isArray(stmsData.teachers)) {
        const tr = stmsData.teachers.find(t => 
          (t.id && String(t.id).trim().toLowerCase() === String(u.id).trim().toLowerCase()) ||
          (t.nameKh && t.nameKh === u.nameKh)
        );
        if (tr) {
          if (!u.photo && tr.photo) {
            u.photo = tr.photo;
            changed = true;
          } else if (!tr.photo && u.photo) {
            tr.photo = u.photo;
            changed = true;
          }
        }
      }
    }
  });

  // Keep active session photo in sync
  if (currentUser) {
    const p = getUserPhoto(currentUser);
    if (p && currentUser.photo !== p) {
      currentUser.photo = p;
      try {
        localStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));
        sessionStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));
      } catch (e) {}
    }
  }

  if (changed) {
    saveData(false);
  }
}
window.syncPhotosAcrossCollections = syncPhotosAcrossCollections;

// Get comprehensive list of all entered students (from trainees & users)
function getAllEnteredStudents() {
  const list = [];
  const seenIds = new Set();
  
  // 1. Add from stmsData.trainees
  (stmsData.trainees || []).forEach(t => {
    if (t && (t.nameKh || t.id)) {
      const id = String(t.id || t.studentId || '').trim();
      const key = (id || t.nameKh).toLowerCase();
      if (!seenIds.has(key)) {
        seenIds.add(key);
        list.push({
          ...t,
          id: id || `STU-${list.length + 1}`,
          photo: getUserPhoto(t) || t.photo || ''
        });
      }
    }
  });

  // 2. Add from stmsData.users where role is trainee
  (stmsData.users || []).forEach(u => {
    if (u && u.role === 'trainee') {
      const id = String(u.studentId || u.id || u.username || '').trim();
      const key = (id || u.nameKh).toLowerCase();
      if (!seenIds.has(key)) {
        seenIds.add(key);
        list.push({
          id: id,
          studentId: u.studentId || id,
          username: u.username || '',
          nameKh: u.nameKh,
          nameEn: u.nameEn || '',
          gender: u.gender || 'ប្រុស',
          dob: u.dob || '2001-01-01',
          className: u.className || u.cohort || 'គរុនិស្សិត',
          cohort: u.cohort || u.className || 'ជំនាន់ទី ៤',
          photo: getUserPhoto(u) || u.photo || '',
          avatar: u.avatar || (u.gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓'),
          status: u.status || 'កំពុងសិក្សា',
          phone: u.phone || ''
        });
      }
    }
  });

  // Sort alphabetically by Khmer name
  list.sort((a, b) => (a.nameKh || '').localeCompare(b.nameKh || '', 'km'));
  return list;
}
window.getAllEnteredStudents = getAllEnteredStudents;

