function getAllSystemClasses() {
  const classSet = new Set();
  const deleted = Array.isArray(stmsData.deletedClasses) ? stmsData.deletedClasses : [];
  
  // 1. From Cohorts
  (stmsData.cohorts || []).forEach(c => {
    (c.classes || []).forEach(cls => {
      if (cls && typeof cls === 'string' && cls.trim() && !deleted.includes(cls.trim())) {
        classSet.add(cls.trim());
      }
    });
  });

  // 2. From Custom Classes
  (stmsData.customClasses || []).forEach(c => {
    const name = typeof c === 'string' ? c.trim() : (c && c.name && typeof c.name === 'string' ? c.name.trim() : '');
    if (name && !deleted.includes(name)) {
      classSet.add(name);
    }
  });

  // 3. From Trainees
  (stmsData.trainees || []).forEach(t => {
    if (t.className && typeof t.className === 'string' && t.className.trim() && !deleted.includes(t.className.trim())) {
      classSet.add(t.className.trim());
    }
  });

  return Array.from(classSet);
}
window.getAllSystemClasses = getAllSystemClasses;

function toKhmerNum(num) {
  const khmerDigits = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  return String(num).replace(/[0-9]/g, d => khmerDigits[parseInt(d, 10)]);
}

function getKhmerFormattedDate(date = new Date()) {
  const days = ['អាទិត្យ', 'ចន្ទ', 'អង្គារ', 'ពុធ', 'ព្រហស្បតិ៍', 'សុក្រ', 'សៅរ៍'];
  const months = ['មករា', 'កុម្ភៈ', 'មីនា', 'មេសា', 'ឧសភា', 'មិថុនា', 'កក្កដា', 'សីហា', 'កញ្ញា', 'តុលា', 'វិច្ឆិកា', 'ធ្នូ'];
  const dayName = days[date.getDay()];
  const dayNum = toKhmerNum(date.getDate());
  const monthName = months[date.getMonth()];
  const yearNum = toKhmerNum(date.getFullYear());
  return `📅 ${dayName} ទី${dayNum} ខែ${monthName} ឆ្នាំ${yearNum}`;
}

function getKhmerGreeting(date = new Date()) {
  const hour = date.getHours();
  if (hour >= 5 && hour < 12) return 'អរុណសួស្តី';
  if (hour >= 12 && hour < 17) return 'ទិវាសួស្តី';
  return 'សាយណ្ហសួស្តី';
}

function getKhmerFirstLetter(name) {
  if (!name) return 'យ';
  const clean = name.trim();
  const match = clean.match(/[\u1780-\u17B3]/);
  return match ? match[0] : clean.charAt(0);
}

function getSubjectTheme(code) {
  const themes = {
    'PED-101': { bg: '#fff1f2', border: '#fecdd3', color: '#e11d48', icon: 'fas fa-chalkboard-teacher', label: 'គរុកោសល្យ' },
    'PSY-102': { bg: '#ecfeff', border: '#a5f3fc', color: '#0891b2', icon: 'fas fa-brain', label: 'ចិត្តវិទ្យា' },
    'MTH-103': { bg: '#eff6ff', border: '#bfdbfe', color: '#2563eb', icon: 'fas fa-calculator', label: 'គណិតវិទ្យា' },
    'KHM-104': { bg: '#fff7ed', border: '#fed7aa', color: '#ea580c', icon: 'fas fa-book-reader', label: 'ភាសាខ្មែរ' },
    'ICT-105': { bg: '#faf5ff', border: '#e9d5ff', color: '#9333ea', icon: 'fas fa-laptop-code', label: 'បច្ចេកវិទ្យា ICT' },
    'RES-106': { bg: '#fffbeb', border: '#fde68a', color: '#d97706', icon: 'fas fa-feather-alt', label: 'ការស្រាវជ្រាវ' },
    'PRAC-107': { bg: '#f0fdf4', border: '#bbf7d0', color: '#16a34a', icon: 'fas fa-school', label: 'កម្មសិក្សា' },
    'COM-108': { bg: '#f0f9ff', border: '#bae6fd', color: '#0284c7', icon: 'fas fa-book-bookmark', label: 'សារគមនាគមន៍' }
  };
  if (themes[code]) return themes[code];

  // Dynamic aesthetic pastel palettes for newly added custom subjects
  const palettes = [
    { bg: '#faf5ff', border: '#e9d5ff', color: '#7e22ce', icon: 'fas fa-graduation-cap', label: 'មុខវិជ្ជា' },
    { bg: '#fff7ed', border: '#ffedd5', color: '#ea580c', icon: 'fas fa-book-open', label: 'មុខវិជ្ជា' },
    { bg: '#f0fdfa', border: '#ccfbf1', color: '#0d9488', icon: 'fas fa-flask', label: 'មុខវិជ្ជា' },
    { bg: '#fdf4ff', border: '#f5d0fe', color: '#c026d3', icon: 'fas fa-atom', label: 'មុខវិជ្ជា' },
    { bg: '#fef2f2', border: '#fee2e2', color: '#dc2626', icon: 'fas fa-lightbulb', label: 'មុខវិជ្ជា' },
    { bg: '#eff6ff', border: '#bfdbfe', color: '#1d4ed8', icon: 'fas fa-shapes', label: 'មុខវិជ្ជា' }
  ];
  let hash = 0;
  for (let i = 0; i < (code || '').length; i++) {
    hash = code.charCodeAt(i) + ((hash << 5) - hash);
  }
  const idx = Math.abs(hash) % palettes.length;
  return palettes[idx];
}

function getActiveTraineeProfile() {
  let profile = null;

  // 1. Check currentTraineeUser if already set
  if (currentTraineeUser && (currentTraineeUser.id || currentTraineeUser.nameKh)) {
    profile = resolveTraineeRecord(currentTraineeUser);
  }

  // 2. Check currentUser if role is trainee
  if (!profile && currentUser && (currentUser.role === 'trainee' || currentRole === 'trainee' || window.currentRole === 'trainee') && (currentUser.id || currentUser.nameKh)) {
    profile = resolveTraineeRecord(currentUser);
  }

  // 3. Check window.authenticatedUser if role is trainee
  if (!profile && window.authenticatedUser && (window.authenticatedUser.role === 'trainee' || currentRole === 'trainee' || window.currentRole === 'trainee') && (window.authenticatedUser.id || window.authenticatedUser.nameKh)) {
    profile = resolveTraineeRecord(window.authenticatedUser);
  }

  // 4. Check persistent storage (sessionStorage and localStorage)
  if (!profile) {
    let saved = null;
    try {
      const rawCur = sessionStorage.getItem('ktpttc_current_user') || localStorage.getItem('ktpttc_current_user');
      if (rawCur) saved = JSON.parse(rawCur);
      if (!saved || (!saved.id && !saved.nameKh)) {
        const rawTrainee = localStorage.getItem('ktpttc_profile_trainee');
        if (rawTrainee) saved = JSON.parse(rawTrainee);
      }
      if (!saved || (!saved.id && !saved.nameKh)) {
        const rawAuth = localStorage.getItem('ktpttc_auth_session');
        if (rawAuth) {
          const authObj = JSON.parse(rawAuth);
          if (authObj && (authObj.role === 'trainee' || authObj.studentId)) saved = authObj;
        }
      }
    } catch (e) {}

    if (saved && (saved.nameKh || saved.id || saved.studentId || saved.username)) {
      profile = resolveTraineeRecord(saved);
    }
  }

  // 5. If STILL null (e.g. fresh installation with no selection yet)
  if (!profile) {
    const allS = typeof getAllEnteredStudents === 'function' ? getAllEnteredStudents() : (stmsData.trainees || []);
    if (allS && allS.length > 0) {
      profile = resolveTraineeRecord(allS[0]);
    } else {
      profile = {
        id: 'ktpttc-2026-st-001',
        nameKh: 'យូសុះ ស៊ីលាល',
        nameEn: 'Yousoh Silal',
        gender: 'ប្រុស',
        dob: '2001-11-16',
        className: 'បរិញ្ញាបត្រ+១ ក្រុម ខ',
        cohort: 'បរិញ្ញាបត្រ+១ ជំនាន់ទី ៤',
        roleLabel: 'គរុនិស្សិត',
        status: 'កំពុងសិក្សា',
        phone: '098 765 432',
        email: 'yousoh.silal@ktpttc.edu.kh',
        avatar: '👨‍🎓',
        attendanceSummary: {
          rate: 98,
          present: 46,
          permission: 2,
          late: 1,
          absent: 0
        },
        scores: {
          'PED-101': { total: 92, grade: 'A', status: 'published', homework: 10, attendance: 10, monthly: 28, semester: 44, final: 44 },
          'PSY-102': { total: 89, grade: 'B+', status: 'published', homework: 9, attendance: 10, monthly: 27, semester: 43, final: 43 },
          'MTH-103': { total: 95, grade: 'A', status: 'published', homework: 10, attendance: 10, monthly: 29, semester: 46, final: 46 },
          'KHM-104': { total: 88, grade: 'B+', status: 'published', homework: 9, attendance: 10, monthly: 26, semester: 43, final: 43 },
          'ICT-105': { total: 90, grade: 'A', status: 'published', homework: 9, attendance: 10, monthly: 27, semester: 44, final: 44 },
          'RES-106': { total: 91, grade: 'A', status: 'published', homework: 10, attendance: 9, monthly: 27, semester: 45, final: 45 },
          'PRAC-107': { total: 97, grade: 'A', status: 'published', homework: 10, attendance: 10, monthly: 29, semester: 48, final: 48 },
          'COM-108': { total: 89, grade: 'B+', status: 'published', homework: 9, attendance: 10, monthly: 26, semester: 44, final: 44 }
        }
      };
    }
  }

  if (profile && !profile.photo && typeof getUserPhoto === 'function') {
    profile.photo = getUserPhoto(profile);
  }

  if (profile && !profile.attendanceSummary) {
    profile.attendanceSummary = { rate: 100, present: 0, permission: 0, late: 0, absent: 0 };
  }
  if (profile && !profile.scores) {
    profile.scores = {};
  }

  currentTraineeUser = profile;
  window.currentTraineeUser = profile;
  try {
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(profile));
  } catch (e) {}

  return profile;
}

function previewTraineeStudent(studentId) {
  const t = resolveTraineeRecord(studentId);
  if (t) {
    currentTraineeUser = t;
    window.currentTraineeUser = t;
    currentUser = { ...currentUser, ...t, role: 'trainee', roleLabel: 'គរុនិស្សិត' };
    localStorage.setItem('ktpttc_profile_trainee', JSON.stringify(t));
    localStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));
    sessionStorage.setItem('ktpttc_current_user', JSON.stringify(currentUser));
    
    // Update Navbar Profile
    const nameEl = document.getElementById('navbarUserName');
    const avatarEl = document.getElementById('navbarUserAvatar');
    if (nameEl) nameEl.textContent = t.nameKh;
    if (avatarEl) {
      if (t.photo) {
        avatarEl.innerHTML = `<img src="${t.photo}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;" />`;
      } else {
        avatarEl.textContent = t.avatar || (t.gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓');
      }
    }
    
    const container = document.getElementById('mainContentArea');
    if (container) renderTraineePortalView(container);
    showToast(`កំពុងមើលគណនីគរុនិស្សិត៖ ${t.nameKh} (${t.id})`, 'info');
  }
}
window.previewTraineeStudent = previewTraineeStudent;

function prevTraineeSemester() {
  currentStreamIndex = currentStreamIndex > 0 ? currentStreamIndex - 1 : TRAINEE_STREAMS.length - 1;
  refreshPortalSubjectsView();
}
window.prevTraineeSemester = prevTraineeSemester;

function nextTraineeSemester() {
  currentStreamIndex = currentStreamIndex < TRAINEE_STREAMS.length - 1 ? currentStreamIndex + 1 : 0;
  refreshPortalSubjectsView();
}
window.nextTraineeSemester = nextTraineeSemester;

function selectTraineeSemester(index) {
  if (index >= 0 && index < TRAINEE_STREAMS.length) {
    currentStreamIndex = index;
    refreshPortalSubjectsView();
  }
}
window.selectTraineeSemester = selectTraineeSemester;

function refreshPortalSubjectsView() {
  const area = document.getElementById('mainContentArea');
  if (!area) return;
  const scrollY = window.scrollY;
  const authUser = window.authenticatedUser;
  const curUser = window.currentUser;
  const isAdmin = (authUser && authUser.role === 'admin') || (curUser && curUser.role === 'admin') || document.body.classList.contains('is-admin-session');
  const isTrainer = (curUser && curUser.role === 'trainer') || (authUser && authUser.role === 'trainer');

  if (isAdmin) {
    renderAdminPortalView(area);
  } else if (isTrainer) {
    renderTrainerPortalView(area);
  } else {
    renderTraineePortalView(area);
  }
  window.scrollTo(0, scrollY);
}
window.refreshPortalSubjectsView = refreshPortalSubjectsView;

function scrollToSubjectsSection() {
  const el = document.getElementById('traineeSubjectsSection') || document.getElementById('adminSubjectsSection');
  if (el) {
    el.scrollIntoView({ behavior: 'smooth' });
  }
}

function renderTraineePortalView(container) {
  const t = getActiveTraineeProfile();
  currentTraineeUser = t;
  window.currentTraineeUser = t;

  const authUser = window.authenticatedUser;
  const isAdmin = (authUser && authUser.role === 'admin') || (currentUser && currentUser.role === 'admin') || document.body.classList.contains('is-admin-session');

  const greeting = getKhmerGreeting();
  const khmerDate = getKhmerFormattedDate();
  const initialLetter = getKhmerFirstLetter(t.nameKh);

  const activeStream = TRAINEE_STREAMS[currentStreamIndex] || TRAINEE_STREAMS[0];
  const targetSemester = activeStream.semester || (currentStreamIndex === 0 ? 'ឆមាសទី ១' : 'ឆមាសទី ២');

  let avatarHtml = '';
  if (t.photo && String(t.photo).trim() !== '') {
    avatarHtml = `<img src="${t.photo}" class="trainee-hero-avatar-img" alt="${t.nameKh}" onerror="this.outerHTML='<span class=\\'trainee-hero-avatar-letter\\'>${initialLetter}</span>'" />`;
  } else {
    avatarHtml = `<span class="trainee-hero-avatar-letter">${initialLetter}</span>`;
  }

  // Filter subjects for the active semester of Bachelor+1
  const allSubjs = (typeof stmsData !== 'undefined' && stmsData && Array.isArray(stmsData.subjects))
    ? stmsData.subjects
    : (typeof KTPTTC_ALL_SUBJECTS !== 'undefined' ? KTPTTC_ALL_SUBJECTS : []);

  const filteredSubjects = allSubjs.filter(s => {
    const sem = (s && s.semester ? String(s.semester).trim() : '');
    if (targetSemester === 'ឆមាសទី ១') {
      return sem === 'ឆមាសទី ១' || sem.includes('១') || !sem;
    } else {
      return sem === 'ឆមាសទី ២' || sem.includes('២') || sem === 'ទាំងពីរឆមាស';
    }
  });

  let subjectsHtml = '';
  if (filteredSubjects.length > 0) {
    subjectsHtml = filteredSubjects.map(subj => {
      const theme = getSubjectTheme(subj.code);
      return `
        <div class="trainee-subject-card" style="--subj-bg:${theme.bg}; --subj-border:${theme.border}; --subj-color:${theme.color};" onclick="openSubjectDetailModal('${subj.code}')" title="ចុចដើម្បីមើលមេរៀន និងលម្អិតមុខវិជ្ជា ${subj.nameKh}">
          <div class="subj-card-icon" style="color:${theme.color};">
            <i class="${theme.icon}"></i>
          </div>
          <div class="subj-card-name">
            ${subj.nameKh}
          </div>
          <div class="subj-card-sub" style="font-size:0.8rem; color:#64748b; font-weight:600; margin-top:auto;">
            ${subj.credits} ក្រេឌីត
          </div>
        </div>
      `;
    }).join('');
  } else {
    subjectsHtml = `
      <div style="grid-column: 1 / -1; padding: 45px 20px; text-align: center; background: #ffffff; border: 2px dashed #cbd5e1; border-radius: 16px; margin: 8px 0;">
        <div style="font-size: 2.5rem; margin-bottom: 10px; color:#94a3b8;"><i class="fas fa-book-reader"></i></div>
        <h4 style="color: #1e3a8a; font-size: 1.05rem; font-weight: 700; margin: 0 0 6px 0;">មិនទាន់មានមុខវិជ្ជាសម្រាប់ ${targetSemester} នៅឡើយទេ</h4>
        <p style="color: #64748b; font-size: 0.85rem; margin: 0;">មុខវិជ្ជា និងកម្មវិធីបណ្តុះបណ្តាលសម្រាប់ឆមាសនេះ នឹងត្រូវដាក់បញ្ចូលក្នុងពេលឆាប់ៗនេះ</p>
      </div>
    `;
  }

  let html = `
    <div class="trainee-portal-container">
      
      <!-- 1. Trainee Hero Banner Card (Deep Blue + Khmer Rosette Watermark) -->
      <div class="trainee-hero-banner">
        <div class="trainee-hero-pattern"></div>
        <div class="trainee-hero-left">
          <div class="trainee-hero-avatar-wrap">
            ${avatarHtml}
          </div>
          <div class="trainee-hero-text">
            <span class="trainee-hero-greeting"><i class="fas fa-graduation-cap" style="color:#60a5fa;"></i> ${greeting}</span>
            <h1 class="trainee-hero-name">${t.nameKh || 'យូសុះ ស៊ីលាល'}</h1>
            <div class="trainee-hero-badges">
              <span class="trainee-badge-pill role"><i class="fas fa-user-graduate"></i> ${t.roleLabel || 'គរុនិស្សិត'}</span>
              <span class="trainee-badge-pill class"><i class="fas fa-chalkboard"></i> ${t.className || 'បរិញ្ញាបត្រ+១'}</span>
              <span class="trainee-badge-pill id"><i class="fas fa-id-badge"></i> ${t.id || 'ktpttc-2026-st-001'}</span>
            </div>
            
            ${isAdmin ? `
              <div style="margin-top:4px; display:inline-flex; align-items:center; gap:8px; background:rgba(255,255,255,0.15); border:1px solid rgba(255,255,255,0.25); border-radius:8px; padding:3px 10px; width:fit-content;">
                <span style="font-size:0.75rem; color:#ffffff; font-weight:700; white-space:nowrap;"><i class="fas fa-user-graduate"></i> ជ្រើសរើសគរុនិស្សិត៖</span>
                <select class="form-input" style="height:26px; font-size:0.76rem; padding:1px 8px; background:#ffffff; color:#0f172a; border-radius:6px; font-weight:700; cursor:pointer; border:none;" onchange="previewTraineeStudent(this.value)">
                  ${(typeof getAllEnteredStudents === 'function' ? getAllEnteredStudents() : (stmsData.trainees || [])).map((s, idx) => `
                    <option value="${escapeHtml(s.id)}" ${s.id === t.id ? 'selected' : ''}>
                      ${idx + 1}. ${escapeHtml(s.nameKh)} (${escapeHtml(s.id)})
                    </option>
                  `).join('')}
                </select>
              </div>
            ` : ''}

            <div class="trainee-hero-date">
              <i class="fas fa-calendar-alt" style="color:#60a5fa;"></i> ${khmerDate}
            </div>
          </div>
        </div>
        <div class="trainee-hero-actions">
          <button class="btn-hero-action btn-hero-sky" onclick="openTraineeTimetableModal()" title="មើលកាលវិភាគសិក្សា">
            <i class="fas fa-calendar-alt"></i> កាលវិភាគ
          </button>
          <button class="btn-hero-action btn-hero-primary" onclick="viewTraineeCard('${t.id}')">
            <i class="fas fa-id-card"></i> កាតសិស្ស
          </button>
          <button class="btn-hero-action btn-hero-emerald" onclick="openTraineeOnlineClassModal()">
            <i class="fas fa-video"></i> ថ្នាក់រៀនអនឡាញ
          </button>
          <button class="btn-hero-action btn-hero-glass" onclick="openProfileSettingsModal()">
            <i class="fas fa-user-edit"></i> កែប្រែព័ត៌មាន
          </button>
        </div>
      </div>

      <!-- 2. Trainee 8 Pastel Hub Menu Grid -->
      <div class="trainee-hub-grid">
        
        <!-- 1. មុខវិជ្ជា (Subjects - Pink) -->
        <div class="trainee-hub-card card-pink" onclick="openTraineeSubjectsModal()">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-chalkboard-teacher"></i></div>
          <div class="hub-card-title">មុខវិជ្ជា</div>
          <div class="hub-card-sub">${allSubjs.length} មុខវិជ្ជា</div>
        </div>

        <!-- 2. កាលវិភាគ (Timetable - Blue) -->
        <div class="trainee-hub-card card-blue" onclick="openTraineeTimetableModal()" title="ចុចដើម្បីមើលកាលវិភាគសិក្សា">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-calendar-alt"></i></div>
          <div class="hub-card-title">កាលវិភាគ</div>
          <div class="hub-card-sub">កាលវិភាគសិក្សាប្រចាំសប្តាហ៍</div>
        </div>

        <!-- 3. ស្លាយ & វីដេអូ (Video Lessons & Slides - Orange) -->
        <div class="trainee-hub-card card-orange" onclick="openTraineeLessonsModal('all', 'slides')">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-chalkboard-teacher"></i></div>
          <div class="hub-card-title">ស្លាយ &amp; វីដេអូ</div>
          <div class="hub-card-sub">មេរៀន E-Learning</div>
        </div>

        <!-- 4. សៀវភៅ (Books / Library - Green) -->
        <div class="trainee-hub-card card-green" onclick="openTraineeLibraryModal()">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-book-open"></i></div>
          <div class="hub-card-title">សៀវភៅ</div>
          <div class="hub-card-sub">បណ្ណាល័យឌីជីថល</div>
        </div>

        <!-- 5. វេទិកា (Forum / Requests - Amber) -->
        <div class="trainee-hub-card card-amber" onclick="openTraineeForumModal()">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-comment-dots"></i></div>
          <div class="hub-card-title">វេទិកា</div>
          <div class="hub-card-sub">ពិភាក្សា & សំណើ</div>
        </div>

        <!-- 6. របាយការណ៍ (Score Reports - Purple) -->
        <div class="trainee-hub-card card-purple" onclick="openTraineeReportsModal()">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-chart-line"></i></div>
          <div class="hub-card-title">របាយការណ៍</div>
          <div class="hub-card-sub">លទ្ធផលពិន្ទុ & និទ្ទេស</div>
        </div>

        <!-- 7. កិច្ចការសិស្ស & កិច្ចព្រមព្រៀង (Practicum & Guidelines - Teal) -->
        <div class="trainee-hub-card card-teal" onclick="openTraineeGuidelinesModal('assignments')">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-tasks"></i></div>
          <div class="hub-card-title">កិច្ចការសិស្ស</div>
          <div class="hub-card-sub">${(stmsData.assignments||[]).length} កិច្ចការដែលបានដាក់</div>
        </div>

        <!-- 8. ផែនការ (Study Plan & Attendance - Sky) -->
        <div class="trainee-hub-card card-sky" onclick="openTraineeAttendanceModal()">
          <div class="hub-card-pattern"></div>
          <div class="hub-card-icon"><i class="fas fa-calendar-alt"></i></div>
          <div class="hub-card-title">ផែនការ</div>
          <div class="hub-card-sub">វត្តមានផ្ទាល់ខ្លួន</div>
        </div>

      </div>

      <!-- 3. Blue Ribbon Strip & Course Row -->
      <div class="trainee-subjects-section" id="traineeSubjectsSection">
        
        <div class="trainee-ribbon-bar">
          <button class="ribbon-arrow-btn" onclick="prevTraineeSemester()" title="ឆមាសមុន">
            <i class="fas fa-chevron-left"></i>
          </button>
          <div class="ribbon-title" style="display:flex; align-items:center; gap:8px;">
            <i class="fas fa-bookmark" style="opacity:0.9;"></i>
            <span>${activeStream.label}</span>
            <span style="font-size:0.75rem; background:rgba(255,255,255,0.22); border:1px solid rgba(255,255,255,0.35); padding:2px 8px; border-radius:12px; font-family:var(--font-battambang); font-weight:700;">
              ${filteredSubjects.length} មុខវិជ្ជា
            </span>
          </div>
          <button class="ribbon-arrow-btn" onclick="nextTraineeSemester()" title="ឆមាសបន្ទាប់">
            <i class="fas fa-chevron-right"></i>
          </button>
        </div>

        <div class="trainee-subjects-body">
          <div class="trainee-subjects-grid">
            ${subjectsHtml}
          </div>
        </div>

      </div>

      <!-- 4. Trainee Real Stats & Academic Overview -->
      <div class="trainee-stats-row">
        
        <!-- My Attendance Summary -->
        <div class="table-card">
          <div class="table-toolbar">
            <strong style="color:#1e3a8a;"><i class="fas fa-calendar-check" style="color:#10b981;"></i> វត្តមានផ្ទាល់ខ្លួន</strong>
            <button class="btn btn-outline" style="height:28px; padding:0 10px; font-size:0.75rem;" onclick="openTraineeAttendanceModal()">ពិនិត្យលម្អិត →</button>
          </div>
          <div style="padding:22px;">
            <div style="display:flex; align-items:baseline; gap:10px; margin-bottom:14px;">
              <span style="font-size:2.4rem; font-weight:800; color:#10b981; line-height:1;">
                ${t.attendanceSummary?.rate || 100}%
              </span>
              <span style="font-size:0.85rem; color:#64748b; font-weight:600;">អត្រាវត្តមានសរុប (គោលដៅ ≥ ៨០%)</span>
            </div>
            <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap:10px; text-align:center; font-size:0.82rem;">
              <div style="background:#f0fdf4; padding:10px 6px; border-radius:8px; border:1px solid #bbf7d0;">
                <div style="font-weight:800; color:#15803d; font-size:1.15rem;">${t.attendanceSummary?.present || 0}</div>
                <div style="color:#166534; font-size:0.75rem; font-weight:600;">វត្តមាន</div>
              </div>
              <div style="background:#fffbeb; padding:10px 6px; border-radius:8px; border:1px solid #fde68a;">
                <div style="font-weight:800; color:#b45309; font-size:1.15rem;">${t.attendanceSummary?.permission || 0}</div>
                <div style="color:#92400e; font-size:0.75rem; font-weight:600;">ច្បាប់</div>
              </div>
              <div style="background:#fff7ed; padding:10px 6px; border-radius:8px; border:1px solid #fed7aa;">
                <div style="font-weight:800; color:#c2410c; font-size:1.15rem;">${t.attendanceSummary?.late || 0}</div>
                <div style="color:#9a3412; font-size:0.75rem; font-weight:600;">យឺត</div>
              </div>
              <div style="background:#fef2f2; padding:10px 6px; border-radius:8px; border:1px solid #fecaca;">
                <div style="font-weight:800; color:#b91c1c; font-size:1.15rem;">${t.attendanceSummary?.absent || 0}</div>
                <div style="color:#991b1b; font-size:0.75rem; font-weight:600;">ឥតច្បាប់</div>
              </div>
            </div>
          </div>
        </div>

        <!-- My Grades Summary -->
        <div class="table-card">
          <div class="table-toolbar">
            <strong style="color:#1e3a8a;"><i class="fas fa-award" style="color:#7c3aed;"></i> លទ្ធផលពិន្ទុ & និទ្ទេសផ្លូវការ</strong>
            <button class="btn btn-outline" style="height:28px; padding:0 10px; font-size:0.75rem;" onclick="openTraineeReportsModal()">ពិនិត្យលម្អិត →</button>
          </div>
          <div style="padding:20px;">
            <p style="font-size:0.83rem; color:#64748b; margin-bottom:12px;">
              ពិន្ទុដែលត្រូវបានផ្សព្វផ្សាយជាផ្លូវការដោយការិយាល័យសិក្សាធិការ KTPTTC៖
            </p>
            <div style="display:flex; flex-direction:column; gap:8px;">
              ${Object.keys(t.scores || {}).map(code => {
                const sc = t.scores[code];
                if (sc.status !== 'published') return '';
                const subj = subjects.find(s => s.code === code);
                return `
                  <div style="display:flex; justify-content:space-between; align-items:center; background:#f8fafc; padding:8px 12px; border-radius:8px; font-size:0.85rem; border:1px solid rgba(0,0,0,0.04);">
                    <div style="display:flex; align-items:center; gap:8px;">
                      <i class="fas fa-check-circle" style="color:#10b981; font-size:0.85rem;"></i>
                      <span style="font-weight:600; color:#1e293b;">${subj?.nameKh || code}</span>
                    </div>
                    <strong>${sc.total} / 100 <span class="badge ${sc.grade==='A'?'badge-present':'badge-published'}" style="margin-left:6px;">${sc.grade}</span></strong>
                  </div>
                `;
              }).join('') || '<div style="color:#94a3b8; font-size:0.85rem; padding:12px; text-align:center;">មិនទាន់មានពិន្ទុត្រូវបានផ្សព្វផ្សាយនៅឡើយទេ។</div>'}
            </div>
          </div>
        </div>

      </div>

    </div>
  `;

  container.innerHTML = html;
}

// Universal Safe Modal Renderer (auto-creates container if missing, clears previous modals)
function showModal(modalHtml) {
  closeStmsModal();
  let container = document.getElementById('modalContainer');
  if (!container) {
    container = document.createElement('div');
    container.id = 'modalContainer';
    document.body.appendChild(container);
  }
  container.innerHTML = modalHtml;
}
window.showModal = showModal;

