// 9. SUBJECT DETAILS MODAL (LEARNING CENTER FOR EACH OF THE 8 SUBJECTS)
// --------------------------------------------------------------------------
function openSubjectDetailModal(code) {
  const t = getActiveTraineeProfile();
  const subj = KTPTTC_ALL_SUBJECTS.find(s => s.code === code) || (stmsData.subjects || []).find(s => s.code === code) || {
    code: code,
    nameKh: 'មុខវិជ្ជាគរុកោសល្យ',
    credits: 3,
    trainer: 'សាស្ត្រាចារ្យ KTPTTC'
  };
  const theme = getSubjectTheme(code);
  const sc = t && t.scores ? t.scores[code] : null;

  const subjectLessons = (stmsData.lessons || []).filter(l => l.subjectCode === code);
  const subjectAssignments = (stmsData.assignments || []).filter(a => a.subjectCode === code);
  const subjectVideos = [...(stmsData.videoLessons || []), ...KTPTTC_VIDEO_LESSONS].filter(v => v.subjectCode === code || v.subject === code);
  const syllabusList = getSubjectSyllabus(code);
  const canEditSyllabus = canUserEditSubjectSyllabus(code);

  let modalHtml = `
    <div class="stms-modal-backdrop" id="subjectDetailModalBackdrop" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-dialog" style="max-width:680px;">
        <div class="stms-modal-header" style="background:${theme.bg}; border-bottom:1px solid ${theme.border}; color:#1e293b;">
          <div style="display:flex; align-items:center; gap:12px;">
            <div style="width:44px; height:44px; border-radius:12px; background:#ffffff; color:${theme.color}; display:flex; align-items:center; justify-content:center; font-size:1.4rem; box-shadow:0 2px 6px rgba(0,0,0,0.06); border:1px solid ${theme.border};">
              <i class="${theme.icon}"></i>
            </div>
            <div>
              <h3 style="color:#1e293b; font-size:1.12rem; margin:0; line-height:1.4;">${subj.nameKh}</h3>
              <p style="color:#64748b; font-size:0.8rem; margin:2px 0 0 0;">កូដ៖ <strong>${subj.code}</strong> • <strong>${subj.credits} ក្រេឌីត</strong> • គ្រូឧទ្ទេស៖ <strong>${subj.trainer}</strong></p>
            </div>
          </div>
          <button class="modal-close-icon" onclick="closeStmsModal()" style="color:#1e293b;">&times;</button>
        </div>
        <div class="stms-modal-body" style="padding:22px; max-height:75vh; overflow-y:auto;">
          
          <!-- Syllabus Outline (Configured by Teacher) -->
          <div style="margin-bottom:18px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
              <h4 style="font-size:0.92rem; color:#1e3a8a; margin:0; display:flex; align-items:center; gap:8px;">
                <i class="fas fa-list-ol" style="color:${theme.color};"></i> មាតិកាសង្ខេបនៃមុខវិជ្ជា (Course Syllabus)
              </h4>
              ${canEditSyllabus ? `
                <button class="btn btn-outline" style="font-size:0.75rem; height:28px; padding:0 10px; color:${theme.color}; border-color:${theme.color}; display:inline-flex; align-items:center; gap:5px; background:rgba(255,255,255,0.9);" onclick="openTeacherSyllabusModal('${subj.code}')" title="កំណត់ និងកែប្រែមាតិកាសង្ខេបមុខវិជ្ជា">
                  <i class="fas fa-edit"></i> កំណត់មាតិកា
                </button>
              ` : ''}
            </div>
            <div style="background:#f8fafc; border-radius:10px; padding:14px; border:1px solid var(--border-color); font-size:0.86rem; line-height:1.8; color:#334155;" id="syllabusContentBox_${subj.code}">
              ${syllabusList.map((item, idx) => `
                <div>• <strong>${item.chapter || `ជំពូកទី ${idx + 1}`}៖</strong> ${item.title}</div>
              `).join('')}
            </div>
          </div>

          <!-- Teacher Uploaded Lessons & Materials -->
          ${subjectLessons.length > 0 ? `
            <div style="margin-bottom:18px;">
              <h4 style="font-size:0.92rem; color:#1e3a8a; margin-bottom:10px; display:flex; align-items:center; justify-content:space-between;">
                <span><i class="fas fa-file-pdf" style="color:#ef4444;"></i> មេរៀន &amp; ស្លាយដែលគ្រូបាន Upload (${subjectLessons.length})</span>
              </h4>
              <div style="display:flex; flex-direction:column; gap:8px;">
                ${subjectLessons.map(l => {
                  const fInfo = getFileIconInfo(l.fileName);
                  return `
                  <div style="background:#ffffff; border:1px solid #e2e8f0; border-radius:10px; padding:12px 14px; display:flex; align-items:center; justify-content:space-between; gap:12px; transition:all 0.2s;" onmouseover="this.style.borderColor='#38bdf8'; this.style.boxShadow='0 3px 12px rgba(2,132,199,0.08)';" onmouseout="this.style.borderColor='#e2e8f0'; this.style.boxShadow='none';">
                    <div style="display:flex; align-items:center; gap:12px; min-width:0; cursor:pointer;" onclick="openLessonSlideViewerModal('${l.id}')" title="ចុចដើម្បីមើលស្លាយមេរៀន">
                      <div class="stms-file-preview-icon ${fInfo.className}" style="width:38px; height:38px; font-size:1.2rem; flex-shrink:0;">
                        <i class="${fInfo.icon}"></i>
                      </div>
                      <div style="min-width:0;">
                        <div style="font-weight:700; color:#1e293b; font-size:0.88rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${l.title}</div>
                        <div style="font-size:0.75rem; color:#64748b; margin-top:2px;">
                          <span>${l.fileName || 'ឯកសារមេរៀន'}</span> • <span class="badge" style="background:#f1f5f9; color:#475569; font-size:0.68rem; padding:1px 6px;">${l.fileSize || '2.4 MB'}</span> • ${l.chapter} • ${l.uploadedBy || 'គ្រូឧទ្ទេស'} (${l.date || ''})
                        </div>
                      </div>
                    </div>
                    <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
                      <button class="btn btn-primary" style="font-size:0.76rem; padding:4px 12px; height:30px; background:linear-gradient(135deg, #0284c7 0%, #0369a1 100%); border:none; color:#ffffff; font-weight:700; border-radius:6px; display:inline-flex; align-items:center; gap:5px; box-shadow:0 2px 5px rgba(2,132,199,0.25); cursor:pointer;" onclick="openLessonSlideViewerModal('${l.id}')" title="ចុចដើម្បីបើកមើលស្លាយមេរៀនផ្ទាល់លើអេក្រង់">
                        <i class="fas fa-desktop"></i> មើលស្លាយ
                      </button>
                      <button class="btn btn-outline" style="font-size:0.76rem; padding:4px 10px; height:30px; color:#2563eb; border-color:#bfdbfe; border-radius:6px; display:inline-flex; align-items:center; gap:4px; cursor:pointer;" onclick="downloadLessonFile('${l.id}')" title="ទាញយកឯកសារ">
                        <i class="fas fa-download"></i> ទាញយក
                      </button>
                    </div>
                  </div>
                `}).join('')}
              </div>
            </div>
          ` : ''}

          <!-- Teacher Uploaded Video Lessons -->
          ${subjectVideos.length > 0 ? `
            <div style="margin-bottom:18px;">
              <h4 style="font-size:0.92rem; color:#1e3a8a; margin-bottom:10px; display:flex; align-items:center; justify-content:space-between;">
                <span><i class="fab fa-youtube" style="color:#ef4444;"></i> វីដេអូបង្រៀនដែលគ្រូបាន Upload (${subjectVideos.length})</span>
              </h4>
              <div style="display:flex; flex-direction:column; gap:8px;">
                ${subjectVideos.map(v => {
                  const ytId = v.youtubeId || extractYouTubeId(v.videoUrl);
                  const thumb = v.thumbnail || (ytId ? getYouTubeThumbnail(v.videoUrl) : '');
                  return `
                    <div style="background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; padding:10px 14px; display:flex; align-items:center; justify-content:space-between; gap:12px;">
                      <div style="display:flex; align-items:center; gap:12px; min-width:0; cursor:pointer;" onclick="playTraineeVideo('${v.id}')">
                        <div style="width:64px; height:42px; border-radius:6px; overflow:hidden; background:#09204a; display:flex; align-items:center; justify-content:center; flex-shrink:0; position:relative;">
                          ${thumb ? `
                            <img src="${thumb}" style="width:100%; height:100%; object-fit:cover;" onerror="this.style.display='none'" />
                            <div style="position:absolute; inset:0; background:rgba(0,0,0,0.25); display:flex; align-items:center; justify-content:center;">
                              <i class="fas fa-play" style="color:#ffffff; font-size:0.7rem;"></i>
                            </div>
                          ` : `
                            <i class="fas fa-play" style="color:#f97316; font-size:0.8rem;"></i>
                          `}
                        </div>
                        <div style="min-width:0;">
                          <div style="font-weight:700; color:#1e293b; font-size:0.86rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(v.title)}</div>
                          <div style="font-size:0.75rem; color:#64748b; margin-top:2px;">
                            <span>${v.duration || '២០ នាទី'}</span> • <span>${v.trainer || 'គ្រូឧទ្ទេស'}</span> • <span>${v.date || ''}</span>
                          </div>
                        </div>
                      </div>
                      <button class="btn btn-primary" style="font-size:0.75rem; padding:4px 12px; height:28px; flex-shrink:0;" onclick="playTraineeVideo('${v.id}')">
                        <i class="fas fa-play"></i> ទស្សនា
                      </button>
                    </div>
                  `;
                }).join('')}
              </div>
            </div>
          ` : ''}

          <!-- Teacher Active Homework / Assignments -->
          ${subjectAssignments.length > 0 ? `
            <div style="margin-bottom:18px;">
              <h4 style="font-size:0.92rem; color:#1e3a8a; margin-bottom:10px; display:flex; align-items:center; gap:8px;">
                <i class="fas fa-tasks" style="color:#f59e0b;"></i> កិច្ចការដែលគ្រូបានដាក់ (${subjectAssignments.length})
              </h4>
              <div style="display:flex; flex-direction:column; gap:8px;">
                ${subjectAssignments.map(hw => `
                  <div style="background:#fffbeb; border:1px solid #fde68a; border-radius:8px; padding:12px 14px;">
                    <div style="display:flex; justify-content:space-between; align-items:flex-start;">
                      <strong style="color:#92400e; font-size:0.88rem;">${hw.title}</strong>
                      <span class="badge badge-warning" style="font-size:0.75rem;">ផុតកំណត់៖ ${hw.dueDate || 'ឆាប់ៗ'}</span>
                    </div>
                    <p style="font-size:0.8rem; color:#78350f; margin:6px 0 8px 0; line-height:1.5;">${hw.description || ''}</p>
                    <div style="display:flex; justify-content:space-between; align-items:center;">
                      <span style="font-size:0.75rem; color:#b45309; font-weight:600;"><i class="fas fa-star"></i> ពិន្ទុ៖ ${hw.points || 10}</span>
                      <button class="btn btn-primary" style="font-size:0.75rem; padding:4px 12px; height:28px;" onclick="submitStudentHomework('${hw.id}')">
                        <i class="fas fa-upload"></i> ប្រគល់កិច្ចការ
                      </button>
                    </div>
                  </div>
                `).join('')}
              </div>
            </div>
          ` : ''}

          <!-- Evaluation Breakdown -->
          <div style="margin-bottom:18px;">
            <h4 style="font-size:0.92rem; color:#1e3a8a; margin-bottom:10px; display:flex; align-items:center; gap:8px;">
              <i class="fas fa-calculator" style="color:${theme.color};"></i> ការបែងចែកភាគរយពិន្ទុ (MoEYS Standard)
            </h4>
            <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap:8px; text-align:center; font-size:0.8rem;">
              <div style="background:#eff6ff; padding:8px 4px; border-radius:6px; border:1px solid #bfdbfe;">
                <div style="font-weight:700; color:#1d4ed8;">១០%</div>
                <div style="font-size:0.74rem; color:#3b82f6;">កិច្ចការស្រាវជ្រាវ</div>
              </div>
              <div style="background:#f0fdf4; padding:8px 4px; border-radius:6px; border:1px solid #bbf7d0;">
                <div style="font-weight:700; color:#15803d;">១០%</div>
                <div style="font-size:0.74rem; color:#22c55e;">វត្តមាន/វិន័យ</div>
              </div>
              <div style="background:#fffbeb; padding:8px 4px; border-radius:6px; border:1px solid #fde68a;">
                <div style="font-weight:700; color:#b45309;">៣០%</div>
                <div style="font-size:0.74rem; color:#eab308;">ប្រឡងប្រចាំខែ</div>
              </div>
              <div style="background:#fdf4ff; padding:8px 4px; border-radius:6px; border:1px solid #f5d0fe;">
                <div style="font-weight:700; color:#a21caf;">៥០%</div>
                <div style="font-size:0.74rem; color:#d946ef;">ប្រឡងឆមាស</div>
              </div>
            </div>
          </div>

          <!-- Current Student Score for this subject -->
          ${sc ? `
            <div style="background:linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%); border:1px solid #86efac; border-radius:10px; padding:14px; margin-bottom:16px;">
              <div style="display:flex; justify-content:space-between; align-items:center;">
                <div>
                  <div style="font-weight:700; color:#166534; font-size:0.95rem;">លទ្ធផលសិក្សារបស់អ្នក៖ ${sc.total} / 100</div>
                  <div style="font-size:0.78rem; color:#15803d; margin-top:3px;">
                    កិច្ចការ៖ ${sc.homework || 10} • វត្តមាន៖ ${sc.attendance || 10} • ប្រចាំខែ៖ ${sc.monthly || 28} • ឆមាស៖ ${sc.semester || sc.final || 44}
                  </div>
                </div>
                <span class="badge badge-present" style="font-size:1.1rem; padding:4px 14px;">និទ្ទេស ${sc.grade}</span>
              </div>
            </div>
          ` : `
            <div style="background:#f8fafc; border:1px dashed #cbd5e1; border-radius:10px; padding:12px; text-align:center; color:#64748b; font-size:0.84rem; margin-bottom:16px;">
              <i class="fas fa-clock" style="color:#94a3b8; margin-right:6px;"></i> លទ្ធផលពិន្ទុឆមាសសម្រាប់មុខវិជ្ជានេះ កំពុងស្ថិតក្នុងដំណើរការវាយតម្លៃដោយគ្រូឧទ្ទេស។
            </div>
          `}

          <!-- Quick Actions: Syllabus & Video Lessons -->
          <div style="display:flex; gap:10px; flex-wrap:wrap; justify-content:flex-end;">
            <button class="btn btn-outline" onclick="closeStmsModal(); openTraineeLibraryModal('${subj.code}');" style="color:#15803d; border-color:#86efac; display:inline-flex; align-items:center; gap:5px;" title="មើលសៀវភៅ និងឯកសារសម្រាប់មុខវិជ្ជា ${subj.nameKh}">
              <i class="fas fa-book-open"></i> សៀវភៅមុខវិជ្ជានេះ
            </button>
            <button class="btn btn-outline" onclick="closeStmsModal(); openTraineeLessonsModal();">
              <i class="fas fa-play-circle" style="color:#ea580c;"></i> មើលវីដេអូបង្រៀន
            </button>
            <button class="btn btn-primary" onclick="downloadSubjectSyllabus('${subj.code}')">
              <i class="fas fa-download"></i> ទាញយក Syllabus (PDF)
            </button>
            <button class="btn btn-outline" onclick="closeStmsModal()">បិទ</button>
          </div>

        </div>
      </div>
    </div>
  `;
  showModal(modalHtml);
}

function renderTraineeAttendanceView(container) {
  const t = getActiveTraineeProfile();

  container.innerHTML = `
    <div class="view-header">
      <div class="view-title-group">
        <h2><i class="fas fa-user-check"></i> កំណត់ត្រាវត្តមានផ្ទាល់ខ្លួន៖ ${t.nameKh}</h2>
        <p>ពិនិត្យវត្តមាន និងអវត្តមានប្រចាំឆមាស • គោលដៅវត្តមានសរុប ≥ ៨០%</p>
      </div>
      <button class="btn btn-outline" onclick="navigateView('trainee-portal')">← ត្រឡប់ក្រោយ</button>
    </div>

    <div class="table-card">
      <div style="padding:24px;">
        <h4 style="color:#1e3a8a; margin-bottom:14px;">អត្រាវត្តមានសរុប៖ <strong style="color:#10b981;">${t.attendanceSummary?.rate || 100}%</strong></h4>
        <p style="font-size:0.85rem; color:#64748b; margin-bottom:20px;">
          គរុនិស្សិតត្រូវមានវត្តមានយ៉ាងតិច <strong>៨០%</strong> នៃម៉ោងសិក្សាសរុប ដើម្បីមានសិទ្ធិចូលរួមប្រឡងបញ្ចប់វគ្គបណ្តុះបណ្តាល។
        </p>

        <div class="data-table-responsive">
          <table class="stms-table">
            <thead>
              <tr>
                <th>កាលបរិច្ឆេទ</th>
                <th>មុខវិជ្ជា</th>
                <th>គ្រូឧទ្ទេស</th>
                <th>ស្ថានភាពវត្តមាន</th>
              </tr>
            </thead>
            <tbody>
              ${(stmsData.attendanceSessions && stmsData.attendanceSessions.length > 0) ? stmsData.attendanceSessions.map(sess => {
                const st = (sess.records && sess.records[t.id]) || 'present';
                const label = st==='present'?'វត្តមាន':st==='absent'?'អវត្តមានគ្មានច្បាប់':st==='permission'?'មានច្បាប់':'មកយឺត';
                const badgeCls = st==='present'?'badge-present':st==='absent'?'badge-absent':st==='permission'?'badge-permission':'badge-late';
                return `
                  <tr>
                    <td>${sess.date}</td>
                    <td><strong>${sess.subjectName || sess.subjectCode}</strong></td>
                    <td>${sess.trainerName || 'គ្រូឧទ្ទេស'}</td>
                    <td><span class="badge ${badgeCls}">${label}</span></td>
                  </tr>
                `;
              }).join('') : `
                <tr>
                  <td colspan="4" style="text-align:center; padding:24px; color:#94a3b8;">
                    មិនទាន់មានកំណត់ត្រាវត្តមាននៅឡើយទេ
                  </td>
                </tr>
              `}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  `;
}

function renderTraineeGradesView(container) {
  const t = getActiveTraineeProfile();

  container.innerHTML = `
    <div class="view-header">
      <div class="view-title-group">
        <h2><i class="fas fa-award"></i> លទ្ធផលសិក្សា និងពិន្ទុផ្លូវការ៖ ${t.nameKh}</h2>
        <p>ពិន្ទុដែលបានផ្ទៀងផ្ទាត់ និងផ្សព្វផ្សាយដោយការិយាល័យសិក្សាធិការ KTPTTC</p>
      </div>
      <button class="btn btn-outline" onclick="navigateView('trainee-portal')">← ត្រឡប់ក្រោយ</button>
    </div>

    <div class="table-card">
      <div class="data-table-responsive">
        <table class="stms-table">
          <thead>
            <tr>
              <th>កូដមុខវិជ្ជា</th>
              <th>ឈ្មោះមុខវិជ្ជា</th>
              <th>កិច្ចការ (10%)</th>
              <th>វត្តមាន (10%)</th>
              <th>ប្រឡងខែ (30%)</th>
              <th>ប្រឡងឆមាស (50%)</th>
              <th>ពិន្ទុសរុប (100)</th>
              <th>និទ្ទេស</th>
            </tr>
          </thead>
          <tbody>
            ${Object.keys(t.scores || {}).map(code => {
              const sc = t.scores[code];
              if (sc.status !== 'published') return '';
              const subj = (stmsData.subjects || []).find(s => s.code === code);
              return `
                <tr>
                  <td><code>${code}</code></td>
                  <td><strong>${subj?.nameKh || code}</strong></td>
                  <td>${sc.homework || 10}</td>
                  <td>${sc.attendance || 10}</td>
                  <td>${sc.monthly || 28}</td>
                  <td>${sc.semester || sc.final || 44}</td>
                  <td><strong style="color:#2563eb; font-size:1rem;">${sc.total}</strong></td>
                  <td><span class="badge ${sc.grade==='A'?'badge-present':'badge-published'}">${sc.grade}</span></td>
                </tr>
              `;
            }).join('') || '<tr><td colspan="8" style="text-align:center; padding:30px; color:#94a3b8;">ពុំទាន់មានពិន្ទុត្រូវបានផ្សព្វផ្សាយនៅឡើយទេ។</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

