function resetBulkImportUI() {
  const fileInput = document.getElementById('stmsBulkFileInput');
  if (fileInput) fileInput.value = '';
  const preview = document.getElementById('bulkPreviewContainer');
  if (preview) preview.style.display = 'none';
  const dropzone = document.getElementById('bulkDropzoneArea');
  if (dropzone) dropzone.style.display = 'block';
  const confirmBtn = document.getElementById('btnConfirmBulkImport');
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.style.opacity = '0.5';
    confirmBtn.style.cursor = 'not-allowed';
  }
  pendingBulkImportData.rows = [];
  pendingBulkImportData.validCount = 0;
}
window.resetBulkImportUI = resetBulkImportUI;

// Process selected file with SheetJS or CSV
function processBulkImportFile(file, role) {
  if (!file) return;
  const isTeacher = role === 'teacher' || role === 'trainer';

  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      let rawRows = [];

      if (typeof XLSX !== 'undefined') {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array', cellDates: true });
        if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
          showToast('ឯកសារគ្មានសន្លឹកកិច្ចការ (Sheet) ណាមួយឡើយ!', 'error');
          return;
        }
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        rawRows = XLSX.utils.sheet_to_json(firstSheet, { header: 1, defval: '' });
      } else {
        const decoder = new TextDecoder('utf-8');
        const text = decoder.decode(e.target.result);
        if (text.startsWith('PK') || /[\x00-\x08\x0E-\x1F\x7F]/.test(text.substring(0, 50))) {
          showToast('ឯកសារ Excel Binary នេះត្រូវការបណ្ណាល័យ SheetJS ដើម្បីអាន។', 'error');
          return;
        }
        rawRows = text.split(/\r?\n/)
          .filter(l => l.trim().length > 0)
          .map(l => l.split(',').map(c => c.trim().replace(/^["']|["']$/g, '')));
      }

      // Filter blank rows
      const rows = rawRows.filter(r => Array.isArray(r) && r.some(c => c !== null && c !== undefined && String(c).trim() !== ''));
      if (rows.length === 0) {
        showToast('ឯកសារពុំមានទិន្នន័យឡើយ!', 'error');
        return;
      }

      // Check for multi-row headers (e.g. Row 0 = category headers, Row 1 = sub-headers)
      let headerRow0 = [];
      let headerRow1 = [];
      let dataRows = rows;

      const firstRowStr = rows[0] ? rows[0].map(c => String(c || '').trim().toLowerCase()).join(' ') : '';
      const hasHeader0 = firstRowStr.includes('អត្តលេខ') || firstRowStr.includes('ឈ្មោះ') || firstRowStr.includes('ភេទ') || 
                         firstRowStr.includes('ថ្នាក់') || firstRowStr.includes('មុខវិជ្ជា') || firstRowStr.includes('name') || 
                         firstRowStr.includes('id') || firstRowStr.includes('gender');

      if (hasHeader0) {
        headerRow0 = rows[0];
        // Check if row 1 is a sub-header row (e.g. "ខេត្ត", "ស្រុក", "ឃុំ", "ភូមិ", "សិស្សថ្មី", "ឪពុក")
        if (rows.length > 1) {
          const secondRowStr = rows[1].map(c => String(c || '').trim().toLowerCase()).join(' ');
          const isSubHeader = secondRowStr.includes('ខេត្ត') || secondRowStr.includes('ស្រុក') || 
                              secondRowStr.includes('ឃុំ') || secondRowStr.includes('ភូមិ') || 
                              secondRowStr.includes('សិស្សថ្មី') || secondRowStr.includes('ឪពុក') || 
                              secondRowStr.includes('ម្តាយ') ||
                              ((rows[1][0] === null || rows[1][0] === undefined || String(rows[1][0]).trim() === '') && 
                               (rows[1][3] === null || rows[1][3] === undefined || String(rows[1][3]).trim() === ''));
          if (isSubHeader) {
            headerRow1 = rows[1];
            dataRows = rows.slice(2);
          } else {
            dataRows = rows.slice(1);
          }
        } else {
          dataRows = rows.slice(1);
        }
      }

      if (dataRows.length === 0) {
        showToast('ឯកសារពុំមានជួរទិន្នន័យសម្រាប់នាំចូលឡើយ!', 'warning');
        return;
      }

      // Map rows
      const parsedRecords = [];
      if (isTeacher) {
        let nextNum = (stmsData.users || []).filter(u => u.role === 'trainer').length + 1;
        dataRows.forEach(cols => {
          const cleanCols = cols.map(c => (c !== null && c !== undefined) ? String(c).trim() : '');
          let id = cleanCols[0] || `USR-TRN-${String(nextNum++).padStart(3, '0')}`;
          let subject = cleanCols[1] || 'PED-101';
          let qualification = cleanCols[2] || 'អនុបណ្ឌិតគរុកោសល្យ';
          let nameKh = cleanCols[3] || cleanCols[0];
          let nameEn = cleanCols[4] || '';
          let genderRaw = cleanCols[5] || '';
          let dobRaw = cols[6];
          let phone = cleanCols[7] || '';
          let email = cleanCols[8] || `${id.toLowerCase()}@ktpttc.edu.kh`;
          let pobProvince = cleanCols[9] || 'ខេត្តក្រចេះ';
          let pobDistrict = cleanCols[10] || '';
          let pobCommune = cleanCols[11] || '';
          let pobVillage = cleanCols[12] || '';
          let curAddress = cleanCols[13] || pobProvince;

          if (id && !id.toUpperCase().startsWith('USR') && !id.toUpperCase().startsWith('TRN') && !/\d/.test(id) && !cleanCols[3]) {
            nameKh = id;
            id = `USR-TRN-${String(nextNum++).padStart(3, '0')}`;
          }
          if (!nameKh || nameKh === id) return;

          const gender = (genderRaw.includes('ស្រី') || genderRaw.toLowerCase().includes('female') || genderRaw.toLowerCase() === 'f') ? 'ស្រី' : 'ប្រុស';
          const dob = parseExcelDate(dobRaw) || '1985-05-15';

          parsedRecords.push({
            id,
            nameKh,
            nameEn,
            gender,
            dob,
            qualification,
            phone,
            email,
            username: id.toLowerCase(),
            password: 'ktpttc123',
            role: 'trainer',
            roleLabel: 'គ្រូឧទ្ទេស / មន្ត្រីបង្រៀន',
            subject,
            status: 'active',
            avatar: gender === 'ស្រី' ? '👩‍🏫' : '👨‍🏫',
            birthplace: { province: pobProvince, district: pobDistrict, commune: pobCommune, village: pobVillage },
            address: { province: curAddress, district: '', commune: '', village: '' }
          });
        });
      } else {
        const colMap = resolveStudentImportColumns(headerRow0, headerRow1);
        let nextRoll = (stmsData.trainees || []).length + 1;

        dataRows.forEach(cols => {
          const cleanCols = cols.map(c => (c !== null && c !== undefined) ? String(c).trim() : '');
          
          let id = cleanCols[colMap.id] || (cleanCols[0] ? cleanCols[0] : `KTPTTC-2026-${String(nextRoll).padStart(3, '0')}`);
          let classGrade = cleanCols[colMap.classGrade] || 'បរិញ្ញាបត្រ+១';
          let group = cleanCols[colMap.group] || '';
          let nameKh = cleanCols[colMap.nameKh] || cleanCols[3];
          let nameEn = cleanCols[colMap.nameEn] || '';
          let genderRaw = cleanCols[colMap.gender] || cleanCols[5] || '';
          let dobRaw = cols[colMap.dob] || cols[6];
          let ageRaw = cleanCols[colMap.age] || cleanCols[7] || '';
          let phone = cleanCols[colMap.phone] || cleanCols[8] || '';
          let username = cleanCols[colMap.username] || cleanCols[9] || id;
          let password = cleanCols[colMap.password] || cleanCols[10] || id || 'ktpttc123';
          
          let pobProvince = cleanCols[colMap.pobProvince] || 'ខេត្តក្រចេះ';
          let pobDistrict = cleanCols[colMap.pobDistrict] || '';
          let pobCommune = cleanCols[colMap.pobCommune] || '';
          let pobVillage = cleanCols[colMap.pobVillage] || '';
          
          let curProvince = cleanCols[colMap.curProvince] || pobProvince;
          let curDistrict = cleanCols[colMap.curDistrict] || '';
          let curCommune = cleanCols[colMap.curCommune] || '';
          let curVillage = cleanCols[colMap.curVillage] || '';
          
          let fatherName = cleanCols[colMap.fatherName] || '';
          let fatherJob = cleanCols[colMap.fatherJob] || '';
          let motherName = cleanCols[colMap.motherName] || '';
          let motherJob = cleanCols[colMap.motherJob] || '';
          let guardianName = cleanCols[colMap.guardianName] || '';
          let guardianJob = cleanCols[colMap.guardianJob] || '';

          if (!nameKh) return;

          const gender = (genderRaw.includes('ស្រី') || genderRaw.toLowerCase().includes('female') || genderRaw.toLowerCase() === 'f') ? 'ស្រី' : 'ប្រុស';
          const dob = parseExcelDate(dobRaw) || '2000-01-01';

          let age = ageRaw;
          if (!age && dob && dob.length >= 4) {
            const birthYr = parseInt(dob.substring(0, 4), 10);
            if (!isNaN(birthYr)) age = String(new Date().getFullYear() - birthYr);
          }

          const className = group ? `${classGrade} ${group}`.trim() : classGrade.trim();

          parsedRecords.push({
            id: String(id).trim(),
            roll: nextRoll++,
            className,
            classGrade,
            group,
            cohort: className,
            trainingType: className.includes('១២+៤') ? "12+4" : className.includes('បរិញ្ញា') ? "បរិញ្ញាបត្រ+១" : "12+2 (បឋមសិក្សា)",
            status: "កំពុងសិក្សា",
            nameKh,
            nameEn,
            gender,
            dob,
            age,
            phone,
            parentPhone: phone,
            username: String(username).trim(),
            password: String(password).trim(),
            avatar: gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓',
            behaviorScore: 100,
            scores: {},
            absentYearCount: 0,
            attendance: 'present',
            birthplace: { province: pobProvince, district: pobDistrict, commune: pobCommune, village: pobVillage },
            address: { province: curProvince, district: curDistrict, commune: curCommune, village: curVillage },
            currentAddress: { province: curProvince, district: curDistrict, commune: curCommune, village: curVillage },
            parents: { fatherName, fatherJob, motherName, motherJob, guardianName, guardianJob },
            attendanceSummary: { present: 0, permission: 0, late: 0, absent: 0, rate: 100.0 }
          });
        });
      }

      if (parsedRecords.length === 0) {
        showToast('ពុំអាចទាញយកទិន្នន័យត្រឹមត្រូវពីឯកសារនេះឡើយ។ សូមពិនិត្យមើលឯកសារគំរូ!', 'warning');
        return;
      }

      // Save pending records
      pendingBulkImportData.rows = parsedRecords;
      pendingBulkImportData.validCount = parsedRecords.length;
      pendingBulkImportData.fileName = file.name;

      // Update UI
      const preview = document.getElementById('bulkPreviewContainer');
      const badge = document.getElementById('bulkValidBadge');
      const nameDisp = document.getElementById('bulkFileNameDisplay');
      const tbody = document.getElementById('bulkPreviewTableBody');
      const confirmBtn = document.getElementById('btnConfirmBulkImport');

      if (preview) preview.style.display = 'block';
      if (badge) badge.innerHTML = `<i class="fas fa-check-circle"></i> រកឃើញទិន្នន័យ ${parsedRecords.length} នាក់`;
      if (nameDisp) nameDisp.textContent = `(ឯកសារ៖ ${file.name})`;

      if (tbody) {
        tbody.innerHTML = parsedRecords.slice(0, 10).map((r, i) => `
          <tr>
            <td style="text-align: center; color: #64748b;">${i + 1}</td>
            <td><code style="color: #2563eb; font-weight: 700;">${r.id}</code></td>
            <td style="font-weight: 700; color: #0f172a;">${r.nameKh}</td>
            <td style="text-align: center;">
              <span class="badge ${r.gender === 'ស្រី' ? 'badge-female' : 'badge-male'}" style="font-size: 0.72rem;">${r.gender}</span>
            </td>
            <td style="text-align: center;">${r.dob}</td>
            <td style="text-align: center; font-weight: 600;">${r.age || '-'}</td>
            <td><span class="badge" style="background: #f1f5f9; color: #334155; font-size: 0.72rem;">${isTeacher ? r.subject : r.className}</span></td>
            <td>${isTeacher ? (r.phone || '-') : (r.parentPhone || r.phone || '-')}</td>
            <td><code style="color: #059669; font-weight: 700;">${r.username || r.id}</code></td>
          </tr>
        `).join('') + (parsedRecords.length > 10 ? `
          <tr>
            <td colspan="9" style="text-align: center; color: #64748b; font-size: 0.78rem; padding: 8px; background: #f8fafc;">
              ... និងទិន្នន័យចំនួន ${parsedRecords.length - 10} នាក់ផ្សេងទៀត
            </td>
          </tr>
        ` : '');
      }

      if (confirmBtn) {
        confirmBtn.disabled = false;
        confirmBtn.style.opacity = '1';
        confirmBtn.style.cursor = 'pointer';
      }

      showToast(`✅ អានឯកសារបានជោគជ័យ! រកឃើញទិន្នន័យចំនួន ${parsedRecords.length} នាក់។`, 'success');

    } catch (err) {
      console.error('File parsing error:', err);
      showToast('កំហុសក្នុងការអានឯកសារ៖ ' + err.message, 'error');
    }
  };

  reader.readAsArrayBuffer(file);
}
window.processBulkImportFile = processBulkImportFile;

// Execute and Commit Bulk Import into STMS Data
function executeBulkImport(role) {
  if (!pendingBulkImportData || !pendingBulkImportData.rows || pendingBulkImportData.rows.length === 0) {
    showToast('ពុំមានទិន្នន័យសម្រាប់នាំចូលឡើយ!', 'warning');
    return;
  }

  const isTeacher = role === 'teacher' || role === 'trainer';
  const records = pendingBulkImportData.rows;
  let importedCount = 0;

  if (isTeacher) {
    if (!Array.isArray(stmsData.users)) stmsData.users = [];
    records.forEach(tr => {
      const idx = stmsData.users.findIndex(u => (u.id && u.id.toLowerCase() === tr.id.toLowerCase()) || (u.nameKh === tr.nameKh && u.role === 'trainer'));
      if (idx !== -1) {
        stmsData.users[idx] = { ...stmsData.users[idx], ...tr };
      } else {
        stmsData.users.push(tr);
      }
      importedCount++;
    });

    saveData();
    closeStmsModal();
    showToast(`🎉 បាននាំចូលទិន្នន័យគ្រូឧទ្ទេសចំនួន ${importedCount} នាក់ដោយជោគជ័យ!`, 'success');
    
    if (currentView === 'trainers') {
      renderTrainersView(document.getElementById('mainContentArea'));
    } else if (currentView === 'admin-portal') {
      renderAdminPortalView(document.getElementById('stmsContentViewport'));
    } else {
      navigateView('trainers');
    }

  } else {
    if (!Array.isArray(stmsData.trainees)) stmsData.trainees = [];
    if (!Array.isArray(stmsData.users)) stmsData.users = [];

    records.forEach(st => {
      const idx = stmsData.trainees.findIndex(t => (t.id && String(t.id).toLowerCase() === String(st.id).toLowerCase()) || (t.nameKh === st.nameKh && t.className === st.className));
      if (idx !== -1) {
        stmsData.trainees[idx] = { ...stmsData.trainees[idx], ...st };
      } else {
        stmsData.trainees.push(st);
      }

      // Sync user login
      const uIdx = stmsData.users.findIndex(u => (u.studentId && String(u.studentId).toLowerCase() === String(st.id).toLowerCase()) || (u.username && String(u.username).toLowerCase() === String(st.username || st.id).toLowerCase()));
      const userObj = {
        id: (uIdx !== -1 && stmsData.users[uIdx].id) ? stmsData.users[uIdx].id : `USR-STU-${String(stmsData.users.length + 1).padStart(3, '0')}`,
        nameKh: st.nameKh,
        nameEn: st.nameEn || '',
        studentId: st.id,
        username: String(st.username || st.id).trim().toLowerCase(),
        password: String(st.password || st.id || 'ktpttc123').trim(),
        role: 'trainee',
        roleLabel: 'គរុនិស្សិត',
        phone: st.phone || st.parentPhone || '',
        className: st.className,
        status: 'active',
        avatar: st.gender === 'ស្រី' ? '👩‍🎓' : '👨‍🎓'
      };
      if (uIdx !== -1) {
        stmsData.users[uIdx] = { ...stmsData.users[uIdx], ...userObj };
      } else {
        stmsData.users.push(userObj);
      }

      importedCount++;
    });

    saveData();
    try {
      localStorage.setItem('krusmart_teacher_custom_students', JSON.stringify(stmsData.trainees));
    } catch (e) {}

    closeStmsModal();
    showToast(`🎉 បាននាំចូលទិន្នន័យគរុសិស្សចំនួន ${importedCount} នាក់ដោយជោគជ័យ!`, 'success');

    if (currentView === 'trainees') {
      renderTraineesView(document.getElementById('mainContentArea'));
    } else if (currentView === 'admin-portal') {
      renderAdminPortalView(document.getElementById('stmsContentViewport'));
    } else {
      navigateView('trainees');
    }
  }
}
window.executeBulkImport = executeBulkImport;

