        group: classToEdit.includes('ក្រុម ខ') ? 'ក្រុម ខ' : classToEdit.includes('ក្រុម គ') ? 'ក្រុម គ' : classToEdit.includes('ក្រុម ឃ') ? 'ក្រុម ឃ' : 'ក្រុម ក',
