function openAdminTimetableModal(selectedClass = null, selectedSemester = null) {
  closeStmsModal();
  const classes = getAllSystemClasses();
  const availableClasses = classes.length > 0 ? classes : ['ថ្នាក់បឋម ១២+២ (ក្រុម ក)', 'ថ្នាក់បឋម ១២+២ (ក្រុម ខ)', 'ថ្នាក់បឋម ១២+៤', 'ថ្នាក់មត្តេយ្យ ១២+២'];
  const targetClass = (selectedClass && selectedClass !== 'all') ? selectedClass : (currentAdminTimetableClassFilter !== 'all' ? currentAdminTimetableClassFilter : availableClasses[0]);
  const targetSemester = selectedSemester || currentAdminTimetableSemesterFilter || 'ឆមាសទី ១';
  const slots = getAllTimetableSlots(targetClass, 'all', targetSemester);

  const modalHtml = `
    <div class="stms-modal-backdrop" id="adminTimetableModal" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-window" style="max-width:1050px; width:95%; max-height:92vh;">
        <div class="modal-header-bar" style="background:linear-gradient(135deg, #1e3a8a 0%, #0284c7 100%); color:#ffffff; padding:16px 22px;">
          <div class="modal-header-title" style="color:#ffffff; font-size:1.15rem; display:flex; align-items:center; gap:10px;">
            <i class="fas fa-calendar-alt" style="color:#fde047;"></i>
            <span>គ្រប់គ្រង និងរៀបចំកាលវិភាគបង្រៀនមេ (Master Institutional Timetable)</span>
          </div>
          <button class="modal-close-icon" onclick="closeStmsModal()" style="color:#ffffff;">&times;</button>
        </div>
        <div class="modal-body-scroll" style="padding:20px;">
          
          <!-- Class & Semester Tabs Selector & Top Actions -->
          <div style="background:#f8fafc; padding:12px 16px; border-radius:10px; border:1px solid #e2e8f0; margin-bottom:16px;">
            <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:10px;">
              <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                <span style="font-size:0.8rem; font-weight:700; color:#1e3a8a;"><i class="fas fa-school"></i> ជ្រើសរើសថ្នាក់៖</span>
                ${availableClasses.map(c => `
                  <button type="button" class="btn ${c === targetClass ? 'btn-primary' : 'btn-outline'}" style="font-size:0.78rem; height:32px; padding:0 12px;" onclick="openAdminTimetableModal('${escapeHtml(c)}', '${escapeHtml(targetSemester)}')">
                    ${escapeHtml(c)}
                  </button>
                `).join('')}
              </div>

              <div style="display:flex; gap:8px; flex-wrap:wrap;">
                <button type="button" class="btn btn-primary" onclick="openAdminAddTimetableSlotModal('${escapeHtml(targetClass)}')" style="font-size:0.8rem; height:32px; background:#10b981; border-color:#34d399;">
                  <i class="fas fa-plus-circle"></i> បន្ថែមម៉ោងថ្មី
                </button>
                <button type="button" class="btn btn-outline" onclick="confirmGenerateStandardTimetable('${escapeHtml(targetClass)}')" style="font-size:0.8rem; height:32px; color:#1d4ed8; border-color:#bfdbfe;">
                  <i class="fas fa-magic"></i> បង្កើតគំរូតាមឆមាស
                </button>
                <button type="button" class="btn btn-primary" onclick="printAdminClassTimetable('${escapeHtml(targetClass)}')" style="font-size:0.8rem; height:32px;">
                  <i class="fas fa-print"></i> បោះពុម្ព
                </button>
              </div>
            </div>

            <!-- Semester Tabs -->
            <div style="display:flex; align-items:center; gap:8px; padding-top:8px; border-top:1px solid #e2e8f0;">
              <span style="font-size:0.8rem; font-weight:700; color:#475569;"><i class="fas fa-layer-group"></i> ឆមាសសិក្សា៖</span>
              <button type="button" class="timetable-pill-tab ${targetSemester === 'ឆមាសទី ១' ? 'active' : ''}" onclick="openAdminTimetableModal('${escapeHtml(targetClass)}', 'ឆមាសទី ១')">
                ឆមាសទី ១ (៥ មុខវិជ្ជាស្នូល)
              </button>
              <button type="button" class="timetable-pill-tab ${targetSemester === 'ឆមាសទី ២' ? 'active' : ''}" onclick="openAdminTimetableModal('${escapeHtml(targetClass)}', 'ឆមាសទី ២')">
                ឆមាសទី ២ (៣ មុខវិជ្ជាអនុវត្ត)
              </button>
              <button type="button" class="timetable-pill-tab ${targetSemester === 'all' ? 'active' : ''}" onclick="openAdminTimetableModal('${escapeHtml(targetClass)}', 'all')">
                គ្រប់ឆមាស
              </button>
            </div>
          </div>

          <!-- Master Timetable Table -->
          <div class="data-table-responsive" style="border:1px solid #e2e8f0; border-radius:10px; overflow:hidden;">
            <table class="stms-table" style="width:100%; border-collapse:collapse; font-size:0.85rem;">
              <thead style="background:#f1f5f9; border-bottom:2px solid #cbd5e1;">
                <tr>
                  <th style="padding:10px; text-align:center; width:80px;">ថ្ងៃ</th>
                  <th style="padding:10px; text-align:center; width:130px;">ម៉ោងសិក្សា</th>
                  <th style="padding:10px;">មុខវិជ្ជា MoEYS</th>
                  <th style="padding:10px;">សាស្ត្រាចារ្យទទួលបន្ទុក</th>
                  <th style="padding:10px; text-align:center; width:110px;">បន្ទប់រៀន</th>
                  <th style="padding:10px; width:130px;">កំណត់សម្គាល់</th>
                  <th style="padding:10px; text-align:center; width:90px;">សកម្មភាព</th>
                </tr>
              </thead>
              <tbody>
                ${(() => {
                  if (slots.length === 0) {
                    return `
                      <tr>
                        <td colspan="7" style="text-align:center; padding:45px 20px; color:#94a3b8;">
                          <i class="fas fa-calendar-times" style="font-size:2.4rem; color:#cbd5e1; margin-bottom:10px; display:block;"></i>
                          <div style="font-size:1rem; font-weight:700; color:#1e3a8a; margin-bottom:6px;">មិនទាន់មានកាលវិភាគបង្រៀនសម្រាប់ «${escapeHtml(targetClass)}» (${escapeHtml(targetSemester === 'all' ? 'គ្រប់ឆមាស' : targetSemester)}) នៅឡើយទេ</div>
                          <p style="font-size:0.82rem; color:#64748b; margin-bottom:14px;">ចុចប៊ូតុងខាងក្រោមដើម្បីបង្កើតកាលវិភាគគំរូ ឬបន្ថែមម៉ោងបង្រៀនដោយផ្ទាល់</p>
                          <button class="btn btn-primary" onclick="confirmGenerateStandardTimetable('${escapeHtml(targetClass)}')" style="font-size:0.8rem;"><i class="fas fa-magic"></i> បង្កើតកាលវិភាគតាមឆមាសស្វ័យប្រវត្តិ</button>
                          <button class="btn btn-outline" onclick="openAdminAddTimetableSlotModal('${escapeHtml(targetClass)}')" style="font-size:0.8rem; margin-left:8px;"><i class="fas fa-plus"></i> បន្ថែមម៉ោងបង្រៀនដំបូង</button>
                        </td>
                      </tr>
                    `;
                  }
                  return TIMETABLE_DAYS.map(day => {
                    const daySlots = slots.filter(s => s.day === day || s.dayFull.includes(day));
                    if (daySlots.length === 0) {
                      return `
                        <tr style="border-bottom:1px solid #f1f5f9; background:#fafafa;">
                          <td style="padding:10px; text-align:center; font-weight:700; background:#f8fafc;">${day}</td>
                          <td colspan="5" style="padding:10px; text-align:center; color:#94a3b8; font-size:0.8rem;">គ្មានម៉ោងសិក្សា / ស្វ័យសិក្សា</td>
                          <td style="padding:10px; text-align:center;">
                            <button class="btn btn-outline" style="height:26px; font-size:0.72rem; padding:0 8px;" onclick="openAdminAddTimetableSlotModal('${escapeHtml(targetClass)}', '${day}')" title="បន្ថែមម៉ោង"><i class="fas fa-plus"></i></button>
                          </td>
                        </tr>
                      `;
                    }
                    return daySlots.map((sl, idx) => {
                      const theme = getSubjectTheme(sl.subjectCode);
                      return `
                        <tr style="border-bottom:1px solid #f1f5f9;">
                          ${idx === 0 ? `<td rowspan="${daySlots.length}" style="padding:10px; text-align:center; font-weight:800; background:#f8fafc; color:#1e3a8a; vertical-align:middle; border-right:1px solid #e2e8f0;">${day}</td>` : ''}
                          <td style="padding:10px; text-align:center; font-weight:700; font-size:0.82rem;">${sl.period}</td>
                          <td style="padding:10px;">
                            <div style="display:flex; align-items:center; gap:6px;">
                              <span style="background:${theme.bg}; color:${theme.color}; border:1px solid ${theme.border}; font-size:0.72rem; font-weight:700; padding:2px 6px; border-radius:4px;">${sl.subjectCode || 'MOEYS'}</span>
                              <strong style="color:#1e3a8a; font-size:0.85rem;">${escapeHtml(sl.subject)}</strong>
                            </div>
                          </td>
                          <td style="padding:10px; font-weight:600; color:#334155;">
                            <i class="fas fa-chalkboard-teacher" style="color:#2563eb; margin-right:4px;"></i>${escapeHtml(sl.trainer)}
                          </td>
                          <td style="padding:10px; text-align:center;">
                            <span class="badge badge-published" style="font-size:0.74rem;">${escapeHtml(sl.room)}</span>
                          </td>
                          <td style="padding:10px; font-size:0.76rem; color:#64748b;">${escapeHtml(sl.notes || '-')}</td>
                          <td style="padding:10px; text-align:center;">
                            <div style="display:flex; gap:4px; justify-content:center;">
                              <button class="roster-action-btn btn-edit-roster" onclick="openAdminEditTimetableSlotModal('${sl.id}')" title="កែប្រែ"><i class="fas fa-edit"></i></button>
                              <button class="roster-action-btn btn-delete-roster" onclick="deleteTimetableSlot('${sl.id}')" title="លុប"><i class="fas fa-trash"></i></button>
                            </div>
                          </td>
                        </tr>
                      `;
                    }).join('');
                  }).join('');
                })()}
              </tbody>
            </table>
          </div>

        </div>
        <div class="modal-footer-bar" style="padding:12px 20px; border-top:1px solid #e2e8f0; display:flex; justify-content:space-between; align-items:center;">
          <div style="font-size:0.8rem; color:#64748b;">
            <i class="fas fa-info-circle" style="color:#2563eb;"></i> ទិន្នន័យកាលវិភាគនឹងផ្សារភ្ជាប់ទៅកាន់ Trainee Portal និង Teacher Dashboard ដោយស្វ័យប្រវត្តិ
          </div>
          <button class="btn btn-outline" onclick="closeStmsModal()">បិទ</button>
        </div>
      </div>
    </div>
  `;

  showModal(modalHtml);
}

// --------------------------------------------------------------------------
// 7. ADMIN MODAL 5: អធិការកិច្ចវត្តមាន (ATTENDANCE AUDIT & DISCIPLINE)
// --------------------------------------------------------------------------
function openAdminAttendanceAuditModal() {
  const trainees = stmsData.trainees || [];
  const concernsList = trainees.filter(t => (t.attendanceSummary?.absent || 0) > 0);

  const modalHtml = `
    <div class="stms-modal-backdrop" id="adminAttendanceModal" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-window" style="max-width:850px; width:95%; max-height:90vh;">
        <div class="modal-header-bar" style="background:#1e3a8a; color:#fff; border-radius:12px 12px 0 0; padding:16px 22px;">
          <div class="modal-header-title" style="color:#fff; font-size:1.1rem; display:flex; align-items:center; gap:10px;">
            <i class="fas fa-clipboard-check" style="color:#fde047;"></i>
            <span>អធិការកិច្ចវត្តមាន &amp; វិន័យទូទាំងសាលា (Attendance &amp; Discipline Audit)</span>
          </div>
          <button class="modal-close-icon" onclick="closeStmsModal()" style="color:#fff;">&times;</button>
        </div>
        <div class="modal-body-scroll" style="padding:20px;">
          
          <div style="background:#fffbeb; border:1px solid #fde68a; border-radius:8px; padding:14px; margin-bottom:16px; color:#92400e; font-size:0.85rem; line-height:1.6;">
            <strong><i class="fas fa-exclamation-triangle"></i> បទបញ្ជាផ្ទៃក្នុងស្តីពីវត្តមានគរុនិស្សិត (MoEYS Standard):</strong>
            <div>• អវត្តមានឥតច្បាប់ <strong>លើសពី ៣ លើក</strong> ត្រូវទទួលការព្រមានជាលាយលក្ខណ៍អក្សរលើកទី ១</div>
            <div>• អវត្តមានសរុបលើសពី <strong>២០%</strong> នៃម៉ោងសិក្សា គ្មានសិទ្ធិប្រឡងបញ្ចប់ឆមាសឡើយ</div>
          </div>

          <h4 style="color:#1e3a8a; margin-bottom:12px; font-size:0.95rem;">
            <i class="fas fa-user-clock"></i> បញ្ជីគរុសិស្សដែលមានកំណត់ត្រាអវត្តមាន (${concernsList.length} នាក់)
          </h4>

          ${concernsList.length > 0 ? `
            <div class="data-table-responsive" style="border:1px solid #e2e8f0; border-radius:8px; overflow:hidden;">
              <table class="stms-table" style="width:100%; border-collapse:collapse; font-size:0.85rem;">
                <thead style="background:#f8fafc; border-bottom:2px solid #e2e8f0;">
                  <tr>
                    <th style="padding:10px;">អត្តលេខ</th>
                    <th style="padding:10px;">ឈ្មោះគរុសិស្ស</th>
                    <th style="padding:10px;">ថ្នាក់រៀន</th>
                    <th style="padding:10px; text-align:center;">អវត្តមានឥតច្បាប់</th>
                    <th style="padding:10px; text-align:center;">អត្រាវត្តមាន</th>
                    <th style="padding:10px; text-align:center;">វិធានការ</th>
                  </tr>
                </thead>
                <tbody>
                  ${concernsList.map(t => `
                    <tr style="border-bottom:1px solid #f1f5f9;">
                      <td style="padding:10px;"><code style="font-weight:700; color:#2563eb;">${t.id}</code></td>
                      <td style="padding:10px;"><strong>${t.nameKh}</strong></td>
                      <td style="padding:10px;">${t.className}</td>
                      <td style="padding:10px; text-align:center;">
                        <span class="badge badge-absent" style="font-size:0.85rem; font-weight:800; padding:4px 10px;">
                          ${t.attendanceSummary?.absent || 0} ដង
                        </span>
                      </td>
                      <td style="padding:10px; text-align:center; font-weight:700; color:#d97706;">
                        ${t.attendanceSummary?.rate || 92}%
                      </td>
                      <td style="padding:10px; text-align:center;">
                        <button class="btn btn-outline" style="height:28px; padding:0 10px; font-size:0.75rem; border-color:#ef4444; color:#dc2626;" onclick="issueAdminDisciplinaryWarning('${t.id}')">
                          <i class="fas fa-file-invoice"></i> ចេញលិខិតព្រមាន
                        </button>
                      </td>
                    </tr>
                  `).join('')}
                </tbody>
              </table>
            </div>
          ` : `
            <div style="background:#f0fdf4; border:1px solid #bbf7d0; border-radius:8px; padding:20px; text-align:center; color:#166534;">
              <i class="fas fa-check-circle fa-2x" style="margin-bottom:8px; display:block;"></i>
              ពុំមានគរុសិស្សណាម្នាក់មានអវត្តមានឥតច្បាប់លើសកម្រិតកំណត់ឡើយ!
            </div>
          `}

        </div>
        <div class="modal-footer-bar" style="padding:12px 20px; border-top:1px solid #e2e8f0; display:flex; justify-content:space-between;">
          <button class="btn btn-primary" onclick="showToast('កំពុងទាញយករបាយការណ៍វត្តមានប្រចាំខែ (Excel)...', 'info')" style="font-size:0.8rem;">
            <i class="fas fa-file-excel"></i> ទាញយករបាយការណ៍វត្តមាន
          </button>
          <button class="btn btn-outline" onclick="closeStmsModal()">បិទ</button>
        </div>
      </div>
    </div>
  `;

  showModal(modalHtml);
}

// Issue Disciplinary Warning
function issueAdminDisciplinaryWarning(traineeId) {
  const t = (stmsData.trainees || []).find(x => x.id === traineeId);
  if (!t) return;
  showToast(`⚠️ បានចេញលិខិតព្រមានជាផ្លូវការលើកទី ១ ជូនគរុសិស្ស «${t.nameKh}» និងបានកត់ត្រាក្នុងសំណុំរឿងសិក្សា!`, 'warning');
}

// --------------------------------------------------------------------------
// 8. ADMIN MODAL 6: ពិន្ទុ & សិក្សាធិការ (MASTER GRADEBOOK APPROVAL & PUBLISHING)
// --------------------------------------------------------------------------
function openAdminGradingModal() {
  const trainees = stmsData.trainees || [];
  const subjects = KTPTTC_ALL_SUBJECTS;

  const modalHtml = `
    <div class="stms-modal-backdrop" id="adminGradingModal" onclick="if(event.target===this) closeStmsModal()">
      <div class="stms-modal-window" style="max-width:1100px; width:96%; max-height:92vh;">
        <div class="modal-header-bar" style="background:#1e3a8a; color:#fff; border-radius:12px 12px 0 0; padding:16px 22px;">
          <div class="modal-header-title" style="color:#fff; font-size:1.1rem; display:flex; align-items:center; gap:10px;">
            <i class="fas fa-award" style="color:#c4b5fd;"></i>
            <span>តារាងពិន្ទុរួម &amp; អនុម័តផ្សព្វផ្សាយជាផ្លូវការ (Master Gradebook Approval)</span>
          </div>
          <button class="modal-close-icon" onclick="closeStmsModal()" style="color:#fff;">&times;</button>
        </div>
        <div class="modal-body-scroll" style="padding:20px;">
          
          ${stmsData.gradebookApprovals?.isApproved ? `
            <div style="background:#ecfdf5; border:1px solid #a7f3d0; border-radius:8px; padding:14px 18px; margin-bottom:16px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
              <div style="font-size:0.85rem; color:#065f46; line-height:1.6;">
                <strong style="display:flex; align-items:center; gap:6px; font-size:0.92rem;"><i class="fas fa-check-circle" style="color:#10b981;"></i> ស្ថានភាព៖ បានផ្ទៀងផ្ទាត់ និងអនុម័តជាផ្លូវការ (Approved &amp; Published)</strong>
                <div>អនុម័តដោយ៖ <strong>${stmsData.gradebookApprovals.approvedBy || 'អ្នកគ្រប់គ្រងប្រព័ន្ធ'}</strong> • កាលបរិច្ឆេទ៖ <strong>${stmsData.gradebookApprovals.approvedAt || ''}</strong></div>
              </div>
              <div style="display:flex; gap:8px;">
                <span class="badge" style="background:#10b981; color:#fff; font-size:0.8rem; padding:6px 12px; border-radius:6px;">
                  <i class="fas fa-stamp"></i> អនុម័តផ្លូវការ
                </span>
                <button class="btn btn-outline" onclick="publishAdminMasterGrades()" style="font-size:0.8rem; height:32px; padding:0 12px;">
                  <i class="fas fa-sync-alt"></i> អនុម័តសារជាថ្មី
                </button>
              </div>
            </div>
          ` : `
            <div style="background:#fffbeb; border:1px solid #fde68a; border-radius:8px; padding:14px 18px; margin-bottom:16px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
              <div style="font-size:0.85rem; color:#92400e; line-height:1.6;">
                <strong>តួនាទី Admin សិក្សាធិការ (Student Monitoring)៖</strong> ផ្ទៀងផ្ទាត់ពិន្ទុដែលគ្រូឧទ្ទេសបានបញ្ចូល ពិនិត្យការគណនាមធ្យមភាគ និងចុចអនុម័តដើម្បីផ្សព្វផ្សាយជាផ្លូវការទៅកាន់គណនីគរុនិស្សិត។
              </div>
              <button class="btn btn-primary" onclick="publishAdminMasterGrades()" style="background:#10b981; border-color:#059669; font-size:0.85rem; padding:8px 16px;">
                <i class="fas fa-check-double"></i> ផ្ទៀងផ្ទាត់ &amp; អនុម័តតារាងពិន្ទុ
              </button>
            </div>
          `}

          <!-- Gradebook Table -->
          <div class="data-table-responsive" style="border:1px solid #e2e8f0; border-radius:8px; overflow-x:auto;">
            <table class="stms-table" style="width:100%; border-collapse:collapse; font-size:0.82rem; white-space:nowrap;">
              <thead style="background:#f8fafc; border-bottom:2px solid #e2e8f0;">
                <tr>
                  <th style="padding:8px 10px;">ល.រ</th>
                  <th style="padding:8px 10px;">ឈ្មោះគរុនិស្សិត</th>
                  <th style="padding:8px 10px;">ថ្នាក់</th>
                  ${subjects.map(s => `<th style="padding:8px 10px; text-align:center;">${s.code}</th>`).join('')}
                  <th style="padding:8px 10px; text-align:center; background:#eff6ff;">មធ្យមភាគ</th>
                  <th style="padding:8px 10px; text-align:center; background:#f0fdf4;">និទ្ទេស</th>
                  <th style="padding:8px 10px; text-align:center;">ស្ថានភាព</th>
                </tr>
              </thead>
              <tbody>
                ${trainees.map((t, idx) => {
                  let sum = 0, count = 0;
                  subjects.forEach(s => {
                    const sc = t.scores?.[s.code]?.total;
                    if (sc !== undefined) {
                      sum += sc;
                      count++;
                    }
                  });
                  const avg = count > 0 ? (sum / count).toFixed(1) : '90.0';
                  const grade = avg >= 90 ? 'A' : avg >= 85 ? 'B+' : avg >= 80 ? 'B' : avg >= 70 ? 'C' : 'D';

                  return `
                    <tr style="border-bottom:1px solid #f1f5f9;">
                      <td style="padding:8px 10px; font-weight:700; color:#64748b; text-align:center;">${idx + 1}</td>
                      <td style="padding:8px 10px;"><strong>${t.nameKh}</strong></td>
                      <td style="padding:8px 10px; font-size:0.75rem; color:#64748b;">${t.className}</td>
                      ${subjects.map(s => {
                        const sc = t.scores?.[s.code]?.total;
                        return `
                          <td style="padding:8px 10px; text-align:center; font-weight:600;">
                            ${sc !== undefined ? sc : `<span style="color:#94a3b8;">-</span>`}
                          </td>
                        `;
                      }).join('')}
                      <td style="padding:8px 10px; text-align:center; font-weight:800; color:#1d4ed8; background:#eff6ff;">
                        ${avg}
                      </td>
                      <td style="padding:8px 10px; text-align:center; font-weight:800; color:#15803d; background:#f0fdf4;">
                        ${grade}
                      </td>
                      <td style="padding:8px 10px; text-align:center;">
                        <span class="badge badge-published" style="font-size:0.72rem; padding:3px 8px;">បានផ្សាយ</span>
                      </td>
                    </tr>
                  `;
                }).join('')}
              </tbody>
            </table>
          </div>

        </div>
        <div class="modal-footer-bar" style="padding:12px 20px; border-top:1px solid #e2e8f0; display:flex; justify-content:space-between;">
          <button class="btn btn-outline" onclick="showToast('កំពុងរៀបចំពុម្ពតារាងពិន្ទុរួម...', 'info'); setTimeout(()=>window.print(), 300);">
            <i class="fas fa-print"></i> បោះពុម្ពតារាងពិន្ទុរួម
          </button>
          <button class="btn btn-outline" onclick="closeStmsModal()">បិទ</button>
        </div>
      </div>
    </div>
  `;

  showModal(modalHtml);
}

// Publish Master Grades (Admin Verification & Official Approval)
function publishAdminMasterGrades() {
  const admin = getActiveAdminProfile();
  const dateStr = new Date().toLocaleDateString('km-KH', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  stmsData.gradebookApprovals = {
    isApproved: true,
    approvedBy: admin.nameKh || 'អ្នកគ្រប់គ្រងប្រព័ន្ធ',
    approvedAt: dateStr,
    status: 'approved',
    note: 'បានផ្ទៀងផ្ទាត់ និងអនុម័តជាផ្លូវការដោយការិយាល័យសិក្សាធិការ'
  };

  (stmsData.trainees || []).forEach(t => {
    if (t.scores) {
      Object.keys(t.scores).forEach(k => {
        t.scores[k].status = 'published';
      });
    }
  });
  saveData();
  showToast('🎉 បានផ្ទៀងផ្ទាត់ និងអនុម័តតារាងពិន្ទុជាផ្លូវការទូទាំងវិទ្យាស្ថាន! គរុនិស្សិតទាំងអស់អាចពិនិត្យពិន្ទុក្នុងគណនីបានភ្លាមៗ។', 'success');
  openAdminGradingModal();
  if (currentView === 'admin-portal') {
    renderAdminPortalView(document.getElementById('stmsContentViewport'));
  }
}

